    ["wailing_caverns"] = {
        { 914, "H", 11, 22, "Nara Wildmane", "Thunder Bluff 75,31", "Nara Wildmane", false, {1490}, {6505, 6504, 270018}, "Gather the four gems from Coblebrain, Lady Anacondra, Pisath and Sephendis, then hand them to Nara Wildmane in Thunder Bluff.", "The series starts with Hamuul Runetotem (Thunder Bluff - Elder Rise 78,28). The four gem-dropping druids are spread across four rooms in the dungeon. ◎ Everyone gets a gem: each of the four bosses drops one for every party member on the quest.", {{10,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {9738, 9739, 9740, 9741}, nil, 5770, "Nara Wildmane", { xp = 2200, rep = { {81, 150, "Thunder Bluff"} } } },
        { 1486, nil, 13, 17, "Nalpak", "The Barrens - Wailing Caverns 47,36", nil, false, nil, {918, 6480}, "Nalpak of the Wailing Caverns wants 20 Mutated Hides.", "All the mutated creatures inside and outside the dungeon can drop the hides. Nalpak is in the cave on the hilltop above the entrance.", {{13,2}, {15,3}, {20,4}, {24,5}}, {6443}, nil, 5767, "Nalpak", { xp = 1600, money = 1800 } },
