        { 962, "H", 14, 18, "Apothecary Zamah", "Thunder Bluff - Spirit Rise 22,20", nil, false, nil, {10919, 270008, 270009}, "Gather 10 Serpentblooms for Apothecary Zamah in Thunder Bluff.", "Can be gathered in the cave before the dungeon and inside it; with Herbalism, Find Herbs shows it on the minimap.", {{14,2}, {16,3}, {21,4}, {25,5}}, {5339}, nil, 3419, "Apothecary Zamah", { xp = 1700, money = 2000, rep = { {68, 150, "Undercity"} } } },
        { 1487, nil, 15, 21, "Ebru", "The Barrens - Wailing Caverns 47,36", nil, false, nil, {6476, 8071, 6481}, "Clear out the Wailing Caverns for Ebru: kill 7 Mutated Destroyers, 7 Venomfangs, 7 Mutated Shamblers and 7 Mutated Fangwind Serpents.", "Ebru is also in the cave on the hilltop above the entrance.", {{15,1}, {17,2}, {19,3}, {24,4}, {28,5}}, nil, nil, 5768, "Ebru", { xp = 2050, money = 2500 } },
        { 6981, nil, 15, 26, nil, "The Glowing Shard drops from (Mutanus the Devourer)", nil, true, nil, nil, "Ask around in Ratchet for more information about this Nightmare Shard.", "Long chain: kill the 4 druids and complete the escort first — only then will the final boss, Mutanus the Devourer, appear; kill him for the Glowing Shard. Then return to Ratchet and talk to that goblin (the one behind that \"something-or-other Equalizer\" quest) — he has no question mark over his head, click him yourself — then head back to the mountaintop outside Wailing Caverns to find Falla Sagewind.", {{15,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {10441}, nil, nil, nil, { xp = 2650 } },
