    ["the_deadmines"] = {
        { 92747, "A", 9, 16, "Alba Fairmoon", "Westfall 52.4,53", nil, false, {92745}, nil, "Collect 8 Suspicious Industrial Supplies from Moonbrook. The crates are not on the town streets — they are inside the building leading to the Deadmines entrance, down the path into the cave.", "Part of the toxin investigation chain: samples from several mines have been checked, and every clue points to the Deadmines beneath Moonbrook. Collect supplies in Moonbrook and turn in to Alba Fairmoon to unlock the explosives preparation section. The two sampling points from the preceding step 'Well Sampling': Molsen Farm 46.2,38.3, Jansen Stead 56.7,18.7. ◎ The supply crates are in the cave leading to the Deadmines entrance, and some are scattered in Moonbrook's buildings (including the Moonbrook schoolhouse) — no elites to fight.", {{9,1}, {12,2}, {14,3}, {19,4}, {23,5}}, nil, nil, 253092, "Alba Fairmoon", { xp = 575, money = 400, rep = { {72, 50, "Stormwind City"} } } },
        { 92753, "A", 9, 18, "Alba Fairmoon", "Westfall 52.4,53", nil, false, {92752}, nil, "Find the furnace deep inside the Deadmines and place the Powerful Blasting Charge beside it; then rendezvous with Alba Fairmoon at the Deadmines exit.", "The dungeon segment of the chain: before entering, the explosives are already prepared by the materiel phase (Sprite Jumpsprocket → Jasper Fel). After planting them, exit the dungeon and meet Alba Fairmoon on the hill behind Moonbrook. ◎ The forge is the room where Gilnid spawns — plant the explosives near the center; after this run do NOT hearth out: leave through the back door and continue the quest at the back entrance.", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253092, "Alba Fairmoon", { xp = 4050, rep = { {72, 50, "Stormwind City"} } } },
        { 92819, "A", 9, 18, "Alba Fairmoon", "Westfall - the hill behind Moonbrook 38.6,83.2", "Destruction in Deadmines", false, {92753}, nil, "Use the remote detonator to set off the charge placed beside the furnace.", "Final step of \"Destruction in Deadmines\": meet Alba Fairmoon on the hill behind Moonbrook and use the detonator to finish.", {{9,1}, {14,2}, {16,3}, {21,4}, {25,5}}, nil, nil, 253279, "Alba Fairmoon", { xp = 140, rep = { {72, 50, "Stormwind City"} } } },
        { 166, "A", 14, 22, "Marshal Gryan Stoutmantle", "Westfall - Sentinel Hill 56,47", "Red Silk Bandanas", false, {155}, {6087, 2041, 2042}, "Kill Edwin VanCleef and bring his head back to Marshal Gryan Stoutmantle.", "The whole series starts with Gryan Stoutmantle (Westfall - Sentinel Hill 56,47). VanCleef is the final boss of The Deadmines, on the top deck of the ship.", {{14,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {3637}, nil, 234, "Marshal Gryan Stoutmantle", { xp = 2600, rep = { {72, 200, "Stormwind City"} } } },
        { 168, "A", 14, 18, "Wilder Thistlenettle", "Stormwind City - Dwarven District 70,41", nil, false, nil, {2037, 2036, 270007}, "Collect 4 Miners' Union Membership Cards and bring them to Wilder Thistlenettle in Stormwind City.", "Membership cards drop from the undead near the dungeon entrance. ◎ The drop rate is very low and not shared (everyone loots their own), so it takes a while.", {{14,2}, {16,3}, {21,4}, {25,5}}, {1894}, nil, 656, "Wilder Thistlenettle", { xp = 1350, rep = { {47, 100, "Ironforge"} } } },
        { 214, "A", 14, 17, "Scout Riell", "Westfall - Sentinel Hill 56, 47", "Red Silk Bandanas", false, {155}, {2074, 2089, 6094, 270005}, "Collect 10 Red Silk Bandanas and bring them to Scout Riell in the watchtower of Sentinel Hill.", "Miners inside and outside the dungeon drop the masks. \"The Defias Traitor\" must be completed before this quest opens.", {{14,2}, {15,3}, {20,4}, {24,5}}, {915}, nil, 820, "Scout Riell", { xp = 1250, rep = { {72, 100, "Stormwind City"} } } },
        { 167, "A", 15, 20, "Wilder Thistlenettle", "Stormwind City - Dwarven District 70,41", nil, false, nil, {1893, 270012, 270013}, "Retrieve the Explorer's League badge and bring it to Wilder Thistlenettle in Stormwind City.", "Badges drop from Foreman Thistlenettle right by the dungeon entrance. ◎ For solo runs wait until level 23 or so: the elites hit hard and chain-pull, and the quest mob is linked to another add.", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {1875}, nil, 656, "Wilder Thistlenettle", { xp = 1550, money = 500, rep = { {47, 100, "Ironforge"} } } },
        { 2040, "A", 15, 20, "Shoni the Shilent", "Stormwind City - Dwarven District 62,34", "Shoni the Shilent", false, {2041}, {7606, 7607, 270015, 270016}, "Retrieve the Compact High-Energy Engine from the Deadmines and bring it to Shoni the Shilent in the Dwarven District of Stormwind City.", "You can take this quest directly, or first do the introductory quest from Gnoarn (Ironforge - Tinker Town 69,50). The engine drops from Sneed's Shredder.", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {7365}, nil, 6579, "Shoni the Shilent", { xp = 1550, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
        { 373, "A", 16, nil, nil, "The Unsent Letter drops from (Edwin VanCleef)", nil, true, nil, nil, "Search Edwin VanCleef's body for a letter that was never sent — it is addressed to Baros Alexston of the Stonemasons' Guild in Stormwind City.", "Baros Alexston (next to Stormwind Cathedral 58,49).", {{16,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {2874}, nil, nil, nil, { xp = 2050, rep = { { 72, 50, "Stormwind City" } } } },
        { 1654, "A", 20, nil, "Jordan Stilwell", "Dun Morogh - Ironforge 52,36", "The Test of Righteousness", false, {1653}, nil, "Gather the materials on Jordan's weapon list — White Stone Oak, Refined Ore, Jordan's Hammer and the Kol Gem — and return to Jordan Stilwell in Ironforge.", "Click [Jordan's Weapon Materials List] to see the details.", {{20,3}, {25,4}, {29,5}}, {6994, 6993, 6895, 7083, 6996}, "Paladin", 6181, "Jordan Stilwell", nil },
