    ["shadowfang_keep"] = {
        { 1013, "H", 16, 26, "Keeper Bel'dugur", "Undercity - The Apothecarium 53,54", nil, false, nil, {6335, 4534, 270030}, "Bring the Book of Ur to Keeper Bel'dugur in the Apothecarium of the Undercity.", "The book is on the bookshelf in Fenrus' (the great worg) room — bottom shelf of the first bookcase on the left as you enter, a blue book. ◎ It respawns after about 10 seconds, so every party member can loot one (not shared). ◎ When Fenrus dies he summons 4 Voidwalkers (non-elite but they hit hard; rogues/cats can drop combat early with Vanish/Prowl).", {{16,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {6283}, nil, 2934, "Keeper Bel'dugur", { xp = 2100, money = 1400, rep = { {68, 100, "Undercity"} } } },
        { 1014, "H", 18, 27, "Dalar Dawnweaver", "Silverpine Forest - The Sepulcher 44,39", nil, false, nil, {6414}, "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", "Arugal is inside the dungeon.", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5442}, nil, 1938, "Dalar Dawnweaver", { xp = 3300, rep = { {68, 200, "Undercity"} } } },
        { 1098, "H", 18, 25, "High Executor Hadrec", "Silverpine Forest - The Sepulcher 43,40", nil, false, nil, {3324, 270023, 270024}, "Find Sentinel Adamant and Sentinel Vincent.", "Deathstalker Adamant is inside the dungeon; Deathstalker Vincent is to the right after entering the courtyard. For the first part you must release the imprisoned deathstalker before the courtyard door opens; the second one can be seen tormented by Arugal right as you enter — work your way around to free him.", {{18,1}, {21,2}, {23,3}, {28,4}, {33,5}}, nil, nil, 1952, "High Executor Hadrec", { xp = 2000, money = 1800, rep = { {68, 100, "Undercity"} } } },
        { 1654, "A", 20, nil, "Jordan Stilwell", "Dun Morogh - Ironforge 52,36", "The Test of Righteousness", false, {1653}, nil, "Gather the materials on Jordan's weapon list — White Stone Oak, Refined Ore, Jordan's Hammer and the Kol Gem — and return to Jordan Stilwell in Ironforge.", "Click [Jordan's Weapon Materials List] to see the details.", {{20,3}, {25,4}, {29,5}}, {6994, 6993, 6895, 7083, 6996}, "Paladin", 6181, "Jordan Stilwell", { xp = 870 } },
        { 1740, nil, 20, nil, "Doan Karhan", "The Barrens 49,57", nil, false, nil, nil, "Collect 3 Shards of Solanruk's Orb and 1 Large Shard, and bring them to Duane Kahan in the Barrens.", "Warlock only! The shards drop from Twilight Acolytes in Blackfathom Deeps; the large shard drops from the Shadowfang Moonrunner wolves in Shadowfang Keep.", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {6914, 6915}, "Warlock", 6247, "Doan Karhan", nil },
    },
    ["excavation_wetlands"] = {
        { 95772, "A", 24, 31, "Dorin Songblade", "Redridge Mountains - Lakeshire 25.6,46.6", nil, false, nil, nil, "Search around Whelgar's Excavation Site for Dorin Songblade's brother Devin.", "Dewin went into the excavation site with the survey team; later you can pick up the follow-up from his corpse inside the dungeon. ◎ The quest giver is in the Lakeshire stables — on your left after crossing the bridge from the flight point.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 956, "Dorin Songblade", { xp = 3150 } },
        { 98815, "A", 24, 28, "James Halloran", "Wetlands - Menethil Harbor 8,55", "Daily Supplies", false, {484}, nil, "Bring 4 Thicket Raptor Hides to leatherworker James Halloran in Menethil Harbor.", "Raptor hides drop from the raptors at the dig site; the prerequisite is Halloran's \"Young Crocolisk Skins\", no need to do \"Daily Delivery\" first.", {{24,2}, {26,3}, {31,4}, {36,5}}, nil, nil, 2094, "James Halloran", { xp = 1150, money = 1200, rep = { {72, 50, "Stormwind City"} } } },
        { 95646, "A", 24, 31, "Greenwarden Rasheer", "Wetlands 56.2,40.6", nil, false, {275}, {271667, 271670, 271664}, "Kill a Highland Terror at the dig site and bring its root core to Rasheer in the Wetlands.", "The Dreadful Root Core drops from Highland Terrors inside the dungeon. ◎ Prerequisite: finish First Mate Fitzsimmons' four-step Wetlands chain — The Greenwarden, Tramping Paws, Fire Taboo, Blisters on The Land — before this quest is offered.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270180}, nil, 1244, "Greenwarden Rasheer", { xp = 3150 } },
        { 95647, "A", 24, 31, "Kaitlin Glassman", "Wetlands - South of Menethil Harbor 11.6,58.4", "Looking for Kaitlin", false, {95737}, nil, "Find Aldin Glassman at the dig site and find out what happened to him.", "The chain starts with 'Looking for Kaitlin' from Lanna (Ashenvale 35.0,48.6).", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, 1480, "Kaitlin Glassman", { xp = 2500 } },
        { 95795, "A", 24, 31, nil, nil, nil, true, {95772}, {271769, 271768}, "Bring news of Devin's fate back to Dorin Songblade in Lakeshire.", "Starts on Dewin's corpse inside the dungeon.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, nil, nil, nil, nil, { xp = 3150 } },
        { 95697, "H", 24, 31, "Bostan", "Orgrimmar - The Drag 57.5,53.4", nil, false, nil, {280766, 280805, 250185, 250077}, "Enter the dig site and bring back 4 Thicket Raptor Meat.", "The meat drops from raptors inside the dungeon; quest giver = cooking trainer Bostan (Orgrimmar - The Drag 57.5,53.4).", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {271100}, nil, 3368, "Bostan", { xp = 3150 } },
        { 95664, "H", 24, 31, nil, nil, nil, true, nil, nil, "Take the Titan Relic to Elder Rise in Thunder Bluff and find someone who can identify it.", "Loot the Titan Relic after killing the final boss, the Relic Guardian; looting it starts this quest. The Titan Relic is not returned on turn-in.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95810, "A", 24, 31, nil, nil, nil, true, nil, nil, "Bring the Titan Relic to Prospector Whelgar in the Wetlands.", "Started by looting the Titan Relic; the Alliance turn-in is Prospector Whelgar at Whelgar's Excavation Site.", {{24,1}, {27,2}, {29,3}, {34,4}, {39,5}}, {270865}, nil, nil, nil, { xp = 630 } },
        { 95682, "H", 24, nil, "Deathstalker Agent", "Wetlands - Hill beside the dig site entrance 51.4,59.2", nil, false, {95663}, {271740, 271732, 271745}, "At the dig site, kill 2 Dragonmaw Saboteurs and 4 Dragonmaw Guards, then bring the spoils back to the Deathstalker Agent outside the dungeon.", "The Dragonmaw dispatches drop from Dragonmaw units inside the instance; the quest giver hides in the hills next to the entrance area. ◎ The prerequisite can be taken from the orc under the stairs in Hammerfall.", nil, {284844}, nil, 13155, "Deathstalker Agent", { xp = 6950 }},
        { 98823, "H", 24, nil, nil, nil, "Elder Knowledge", false, {95664}, {271766, 271767, 271719}, "Bring the Titan Relic to Muln Earthfury at Skywatcher Heights in northwestern Mulgore.", "Follow-up to \"Knowledge of the Elders\"; the relic drops from the final boss, the Ruins Guardian. ◎ Turning in \"Knowledge of the Elders\" consumes the relic, so this quest can't be completed, and it can't be picked up again after abandoning.", nil, {270865}, nil, 9087, "Bashana Runetotem", { xp = 6950 } },
        { 95809, "A", 24, nil, nil, nil, "Something in the Thicket", false, {95647}, {1710, 3827, 2459, 280766}, "Bring the Woven Grass Heart back to Kaitlin Glassman in Menethil Harbor.", "After completing \"Something in the Brush\", the token Aldin gives you, the Reed-woven Heart, starts this quest.", nil, {270901}, nil, nil, nil, { xp = 6150 } },
        { 98824, "A", 24, nil, "Prospector Whelgar", nil, "Delivering the Lost Relic", false, {95810}, {271716, 271767, 271766}, "Bring the Titan relic to High Explorer Magellas in the Hall of Explorers in Ironforge.", "Follow-up to \"Delivering the Lost Relic\", continued with Surveyor Verga; the relic drops from the final boss, the Ruins Guardian. ◎ Same issue: turning in the previous step loses the Titan Relic, so this can't be turned in.", nil, {270865}, nil, 1077, "Prospector Whelgar", { xp = 6150 } },
    },
    ["blackfathom_deeps"] = {
        { 971, "A", 18, 23, "Gerrig Bonegrip", "Ironforge - The Forlorn Cavern 50,5", nil, false, nil, {6743}, "Bring the Lorgalis Manuscript to Gerrig Bonegrip in Ironforge.", "The manuscript lies in a pool inside the dungeon — in the water area of the turtle-king room: an underwater alcove chest on the right as you enter, guarded by 1-2 naga (single-pullable).", {{18,1}, {19,2}, {21,3}, {26,4}, {31,5}}, {5359}, nil, 2786, "Gerrig Bonegrip", { xp = 2750, rep = { {47, 50, "Ironforge"} } } },
        { 6563, "H", 17, 22, "Je'neu Sancrea", "Ashenvale - Zoram'gar Outpost 11,33", "The Essence of Aku'Mai", false, {6562}, nil, "Collect 20 Aku'mai Sapphires and bring them to Je'neu Sancrea in Ashenvale.", "The prerequisite \"Trouble in the Deeps\" can be picked up from Tsunaman (Stonetalon Mountains - Sun Rock Retreat 47,64). The sapphires grow on the cave walls of the tunnel leading to the Blackfathom Deeps entrance.", {{17,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {16784}, nil, 12736, "Je'neu Sancrea", { xp = 1750, money = 1400, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 6564, "H", 17, 22, "A Damp Note", "Drops - see notes", nil, false, {6562}, nil, "Deliver the Damp Note to Je'neu Sancrea in Ashenvale; then kill Lorgus Jett in Blackfathom Deeps and report back.", "Requires accepting 'The Crystals of Aku'mai' first before it drops |cff999999(Coupdegrace feedback)|r. The note drops from Tide Priestesses at the Blackfathom Deeps entrance (about 5%). Je'neu Sancrea (Ashenvale - Zoram'gar Outpost 11,33). Lorgus Jett (inside the dungeon).", {{17,1}, {18,2}, {20,3}, {25,4}, {29,5}}, {16790}, nil, nil, nil, { xp = 1300, money = 1100, rep = { {530, 75, "Darkspear Trolls"} } } },
        { 6565, "H", 17, 26, "Je'neu Sancrea", "Ashenvale", nil, false, {6564}, {17694, 17695}, nil, nil, {{17,1}, {22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 12736, "Je'neu Sancrea", { xp = 2650, money = 4000, rep = { {530, 150, "Darkspear Trolls"} } } },
        { 1198, "A", 18, nil, "Dawnwatcher Shaedlass", "Darnassus - Craftsmen's Terrace 55,24", nil, false, nil, nil, "Enter Blackfathom Deeps and find Argent Guard Thaelrid.", "Selreid is inside the instance, underwater southwest of the turtle pool. The starting NPC is in the Alliance capital Darnassus; Horde players will die a lot to get this quest.", {{18,1}, {20,2}, {22,3}, {27,4}, {32,5}}, nil, nil, 4786, "Dawnwatcher Shaedlass", { xp = 5700, rep = { { 529, 150, "Argent Dawn" }, { 69, 150, "Darnassus" } } } },
        { 1200, "A", 18, 27, "Argent Guard Thaelrid", "Blackfathom Deeps", "Blackfathom Villainy", true, {1198}, {7001, 7002, 270031, 270032}, "Retrieve the head of Sleepwalker Kerlis and bring it to Sentinel Selgolm in Darnassus.", "Kelris is inside the instance; Dawnwatcher Selgorm (Darnassus - Craftsmen's Terrace 55,24). Careful: lighting the fire next to Kelris triggers enemy reinforcements.", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5881}, nil, 4787, "Scout Thaelrid", { xp = 3300, money = 6500, rep = { {529, 200, "Argent Dawn"}, {69, 200, "Darnassus"} } } },
        { 1275, "A", 18, 24, "Gershala Nightwhisper", "Darkshore - Auberdine 38,43", "Researching the Corruption", false, {3765}, {7003, 7004, 270021}, "Collect 8 Corrupted Brainstems for Gershala Nightwhisper in Auberdine.", "The prerequisite can be taken from Argos Nightwhisper (Stormwind City - The Park 36,67). All naga inside and outside the dungeon drop brain stems.", {{18,1}, {20,2}, {22,3}, {27,4}, {32,5}}, {5952}, nil, 8997, "Gershala Nightwhisper", { xp = 2400, money = 3500, rep = { {69, 150, "Darnassus"} } } },
        { 6561, "H", 18, 27, "Scout Thaelrid", "Blackfathom Deeps", nil, true, nil, {7001, 7002, 270031, 270032}, "Bring the head of Sleepwalker Kerlis back to Bashana Runetotem in Thunder Bluff.", "Kelris is inside the instance; Bashana Runetotem (Thunder Bluff - Elder Rise 70,33). Careful: lighting the fire next to Kelris draws enemies.", {{18,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {5881}, nil, 4787, "Scout Thaelrid", { xp = 3300, money = 6500, rep = { {529, 200, "Argent Dawn"}, {81, 200, "Thunder Bluff"} } } },
        { 1199, "A", 20, 25, "Argent Guard Manados", "Darnassus - Craftsmen's Terrace 55,23", nil, false, nil, {6998, 7000, 270025}, "Collect 10 Twilight Pendants and bring them to Argent Guard Manados in Darnassus.", "Every Twilight's Hammer enemy drops pendants. ◎ In the current version the turn-in awards all 3 rewards at once.", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {5879}, nil, 4784, "Argent Guard Manados", { xp = 2550, rep = { {529, 150, "Argent Dawn"}, {69, 150, "Darnassus"} } } },
        { 1740, nil, 20, nil, "Doan Karhan", "The Barrens 49,57", nil, false, nil, { 6898, 15109 }, "Collect 3 Shards of Solanruk's Orb and 1 Large Shard, and bring them to Duane Kahan in the Barrens.", "Warlock only! The shards drop from Twilight Acolytes in Blackfathom Deeps; the large shard drops from the Shadowfang Moonrunner wolves in Shadowfang Keep.", {{20,1}, {21,2}, {23,3}, {28,4}, {33,5}}, {6914, 6915}, "Warlock", 6247, "Doan Karhan", { xp = 5100 } },
        { 6921, "H", 21, 27, "Je'neu Sancrea", "Ashenvale - Zoram'gar Outpost 11,33", nil, false, nil, nil, "Bring the Core of the Deeps to Je'neu Sancrea at Zoram'gar Outpost in Ashenvale.", "The Fathom Core is in the water inside the dungeon. Once you take it, Baron Aquanis will appear and attack — he drops a quest item; bring that to Je'neu Sancrea as well. The core is underwater in the center of the big pool before the last boss (no need to enter the boss's room).", {{21,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {16762}, nil, 12736, "Je'neu Sancrea", { xp = 2750, money = 4500, rep = { {530, 150, "Darkspear Trolls"} } } },
    },
    ["the_stockade"] = {
        { 391, "A", 16, 29, "Warden Thelwater", "Stormwind City - The Stockade 51,69", "The Stockade Riots", false, {389}, nil, "Kill Bazil Thredd and bring his head to Warden Thelwater.", "For prerequisites see The Deadmines' 'The Defias Brotherhood' series. Bazil Thredd is inside the instance.", {{16,1}, {25,2}, {27,3}, {32,4}, {37,5}}, {2926}, nil, 1719, "Warden Thelwater", { xp = 2350, money = 2500, rep = { {72, 100, "Stormwind City"} } } },
        { 377, "A", 22, 26, "Councilman Millstipe", "Duskwood - Darkshire 72,47", nil, false, nil, {2033, 2906}, "Kill Dexter Ward and bring his hand back to Councilman Millstipe of Darkshire as proof.", "Dexter Ward is inside the dungeon.", {{22,2}, {24,3}, {29,4}, {34,5}}, {3628}, nil, 270, "Councilman Millstipe", { xp = 2100, rep = { {72, 100, "Stormwind City"} } } },
        { 378, "A", 22, 27, "Motley Garmason", "Wetlands - Dun Modr 49,18", "The Fury Runs Deep", false, {303}, {3562, 1264}, "Bring the head of Kam Deepfury to Motley Garmason in Dun Modr.", "The prerequisite is also taken from Motley Garmason. Kam Deepfury is inside the dungeon.", {{22,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {3640}, nil, 1074, "Motley Garmason", { xp = 2750, rep = { {47, 150, "Ironforge"} } } },
        { 386, "A", 22, 25, "Guard Berton", "Redridge Mountains - Lakeshire 26,46", nil, false, nil, {3400, 1317}, "Bring the head of Targorr to Guard Berton in Lakeshire.", "Targorr is inside the dungeon. He usually spawns in the first cell on the right or the second cell on the left of the central wing; rarely, in the northernmost cell between the two wings.", {{22,2}, {23,3}, {28,4}, {33,5}}, {3630}, nil, 859, "Guard Berton", { xp = 2000, rep = { {72, 100, "Stormwind City"} } } },
        { 387, "A", 22, 26, "Warden Thelwater", "Stormwind City - The Stockade 51,69", nil, false, nil, nil, "Take stock of the Stockade for Warden Thelwater of Stormwind: kill 10 Defias Convicts, 8 Defias Criminals and 8 Defias Insurgents.", "The quest is issued by the warden outside the dungeon.", {{22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 1719, "Warden Thelwater", { xp = 2650, money = 4000, rep = { {72, 150, "Stormwind City"} } } },
        { 388, "A", 22, 26, "Nikova Raskol", "Stormwind City - Old Town 75,63", nil, false, nil, nil, "Collect 10 Red Wool Bandanas and bring them to Nikova Raskol in Stormwind City.", "Nikova Raskov wanders around Old Town; nearly every enemy in the Stockade drops a mask.", {{22,2}, {24,3}, {29,4}, {34,5}}, {2909}, nil, 1721, "Nikova Raskol", { xp = 2650, money = 4000, rep = { {72, 150, "Stormwind City"} } } },
    },
    ["city_of_dalaran"] = {
        { 92457, "A", 24, 33, "Image of Archmage Modera", "Alterac Mountains - outside the City of Dalaran entrance", nil, false, {92432}, {279837, 279838}, "For Archmage Modera outside Dalaran, defeat 8 Seeking Remnants, 8 Saturated Remnants and 8 Mana Echoes inside the City of Dalaran.", "Starts outside the dungeon (Image of Archmage Modera), and starts and ends at the same place. All three arcane elementals are inside the City of Dalaran: Seeking Remnant, Saturated Remnant, Mana Echo.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 269127, "Image of Archmage Modera", { xp = 9400, rep = { {2740, 100, "Kirin Tor"} } } },
        { 92489, "A", 24, 33, "High Sorcerer Andromath", "Stormwind City - Mage Quarter", nil, false, nil, {251962, 279849}, "For High Sorcerer Andromath of Stormwind, destroy the Arcanic Enigma within the City of Dalaran.", "Starts and ends with High Sorcerer Andromath in the Stormwind Mage Quarter. The Arcanic Enigma is an elite on the Path of Revival; it silences for 10 seconds and summons Arcane Mana Sprouts.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5694, "High Sorcerer Andromath", { xp = 9400 } },
        { 92432, "A", 30, 33, "Emissary Jacques", "Hillsbrad Foothills - Southshore 48.3,60.1", "Urgent Plea", false, nil, nil, "Report to the Image of Archmage Modera near the City of Dalaran.", "Accept from Emissary Jacques in Southshore, Hillsbrad Foothills (shareable). Alliance chain: A Call for Aid (Emissary Jacques → Image of Archmage Modera) → Source of the Unrest (accept at the Image of Archmage Modera, enter the city to collect the Arcane Mote; the 'Dalaran Sewer Key' is given automatically) → Friend of the Kirin Tor (accept at the Image of Archmage Modera, turn in to Archmage Celindra in the Violet Citadel).", {{30,1}, {31,2}, {36,3}, {42,4}}, nil, nil, 247264, "Emissary Jacques", { xp = 660, rep = { { 2740, 10, "Kirin Tor" } } }},
        { 92458, "A", 24, 33, "Image of Archmage Modera", "Silverpine Forest - Outside the City of Dalaran instance", "Source of the Unrest", false, {92432}, {279839, 279840, 279841}, "Recover the Arcane Mote inside the City of Dalaran for the Image of Archmage Modera outside the city.", "Accept and turn in at the Image of Archmage Modera outside the dungeon. Alliance chain: A Call for Aid (accept from Emissary Jacques in Southshore, report to the Image of Archmage Modera) → this quest (enter the city to collect the Arcane Mote) → Friend of the Kirin Tor (accept at the Image of Archmage Modera, turn in to Archmage Celindra in the Violet Citadel). Accepting this quest automatically gives the 'Dalaran Sewer Key'.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "Image of Archmage Modera", { xp = 9400, rep = { {2740, 100, "Kirin Tor"} } } },
        { 92459, "A", 24, 33, "Image of Archmage Modera", "Silverpine Forest - Outside the City of Dalaran instance", "Friend of the Kirin Tor", false, {92458}, nil, "Take the Arcane Particles back to the City of Dalaran and speak with Archmage Celindra.", "Picked up at the Image of Archmage Modera; the quest provides \"Arcane Particles\". Enter the city and turn in to Archmage Selindra at the Violet Citadel; if the Alliance is blocked outside the city, turn in outside the dungeon entrance.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 269127, "Image of Archmage Modera", { xp = 265, rep = { { 2740, 10, "Kirin Tor" } } } },
        { 92456, "A", 24, 33, "Shylamiir", "Stormwind City - Mage Quarter", nil, false, nil, {279835, 279836}, "Gather a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City.", "Starts and ends with Shylamiir in Stormwind's Mage Quarter. The Fel-Infused Blossoms come from the fel vegetation in the city, mostly around the Fel Ancient.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5502, "Shylamiir", { xp = 9400 } },
        { 96986, "H", 24, 33, "Melisara", "Hillsbrad Foothills - Tarren Mill", nil, false, nil, {251963, 251965}, "For Melisara in Tarren Mill, defeat Atrexis the Grave Knight inside the City of Dalaran.", "Starts and ends with Melisara in Tarren Mill. Atrexis is at the ritual circle deep in the sewers; he disarms his current target — the tank should use damage reduction while disarmed.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 2278, "Melisara", { xp = 9400 } },
        { 96988, "H", 24, 33, "Doctor Martin Felben", "Undercity - The Apothecarium", nil, false, nil, {279847, 279848}, "Collect 6 Cracked Sentry Cores from the City of Dalaran for Doctor Martin Felben in Undercity.", "Starts and ends with Doctor Martin Felben in Undercity. Cracked Sentry Cores mostly drop from the arcane golem/sentry-type mobs in the city.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 11044, "Doctor Martin Felben", { xp = 9400 } },
        { 92434, "H", 30, 34, "Magus Wordeen Voidglare", "Hillsbrad Foothills - Tarren Mill 61.4,20.8", "Blood in the Streets", false, { 545, 93680 }, nil, "Search along Lordamere Lake for a way into the City of Dalaran.", "Accept from Magus Wordeen Voidglare in Tarren Mill (requires finishing his other quests first); the quest provides the 'Grimy Key'. Follow the shore of Lordamere Lake to the sewer entrance at the northern edge of the City of Dalaran, slip into the city, and turn in to the Image of Archmage Modera outside the city.", {{30,1}, {32,2}, {37,3}, {43,4}}, {279469}, nil, 2410, "Magus Wordeen Voidglare", { xp = 270 }},
        { 96984, "H", 24, 33, "Image of Archmage Modera", "Silverpine Forest - Outside the City of Dalaran instance", "Source of the Unrest", false, {92434}, {279842, 279843, 279844}, "Recover the Arcane Mote inside the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill.", "Accept at the Image of Archmage Modera outside the dungeon; turn in back to Wordeen Voidglare in Tarren Mill. Horde chain: Blood in the Streets (accept in Tarren Mill, sneak into Dalaran, turn in at the Image of Archmage Modera) → this quest (enter the city to collect the Arcane Mote) → Shrewd Negotiations (accept back in Tarren Mill, turn in to Archmage Celindra in the Violet Citadel). Accepting this quest automatically gives the 'Dalaran Sewer Key'.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "Image of Archmage Modera", { xp = 9400 } },
        { 97287, "H", 24, 33, "Magus Wordeen Voidglare", "Hillsbrad Foothills - Tarren Mill 61.4,20.8", "Shrewd Negotiations", false, {96984}, nil, "Take the Arcane Particles back to the City of Dalaran and speak with Archmage Celindra.", "Accept from Magus Wordeen Voidglare in Tarren Mill; the quest provides the 'Arcane Mote'. Turn in to Archmage Celindra in the Violet Citadel; if the Horde is kept outside the city, turn in outside the dungeon entrance instead (at the Image of Archmage Modera, who hands out the key).", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 2410, "Magus Wordeen Voidglare", { xp = 270 }},
        { 96987, "H", 24, 33, "Rexxie Copperclutch", "Alterac Mountains - near the Dalaran sewer entrance", nil, false, nil, { 279845, 279846 }, "Retrieve the Founding of Dalaran from the City of Dalaran and bring it to Rexxie Copperclutch near the sewer entrance.", "The quest giver Rexxie Copperclutch stands near the sewer entrance. \"The Founding of Dalaran\" is a quest item everyone in the group can loot, so a whole group can complete it.", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, nil, "Rexxie Copperclutch", { xp = 9400 } },
    },
    ["gnomeregan"] = {
        { 2843, "H", 20, 35, "Scooty", "Stranglethorn Vale - Booty Bay 27,77", "Gnomer-gooooone!", false, {2842}, {9173}, "Wait while Scooty fixes the goblin teleporter.", "The prerequisite can be picked up from Sovik (Orgrimmar - Valley of Honor 75,25). After completing it you can use the Booty Bay teleporter. ◎ You can throw away the Goblin Transponder after use; if you lose it, just tell Scooty and he'll give you another.", {{20,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7853, "Scooty", nil },
        { 2922, "A", 20, 26, "Tinkmaster Overspark", "Ironforge - Tinker Town 69,50", "Tinkmaster Overspark", false, {2923}, nil, "Bring the Storage Core of Techbot to Tinkmaster Overspark in Ironforge.", "The prerequisite can be taken from Brother Sarno (Stormwind City - Cathedral Square 51,48). Techbot is near the back entrance, before you enter the dungeon.", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {9277}, nil, 7944, "Tinkmaster Overspark", { xp = 2650, money = 2000, rep = { {54, 150, "Gnomeregan Exiles"} } } },
        { 2926, "A", 20, 27, "Ozzie Togglevolt", "Dun Morogh - Kharanos 45,49", "Gnogaine", false, {2927}, nil, "Use the Empty Lead Vial to collect Irradiated Dust from Irradiated Invaders or Irradiated Pillagers, fill it, and bring it to Ozzie Togglevolt in Kharanos.", "The prerequisite is from Gnoarn (Ironforge - Tinker Town 69,50). How to sample: use the Empty Leaden Collection Phial on living Irradiated Invaders/Pillagers.", {{20,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {9284, 9283}, nil, 1268, "Ozzie Togglevolt", { xp = 2200, money = 2200, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 2928, "A", 20, 30, "Shoni the Shilent", "Stormwind City - Dwarven District 63,34", nil, false, nil, {9608, 9609, 270045}, "Collect 24 Mechanical Gizzards and bring them to Shoni in Stormwind City.", "All the robots drop gizzards.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9309}, nil, 6579, "Shoni the Shilent", { xp = 2450, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
        { 2953, nil, 25, 30, "Super Cleaner 5200", "Gnomeregan", nil, false, {2952}, nil, nil, nil, {{25,1}, {26,2}, {28,3}, {33,4}, {40,5}}, { 9308 }, nil, nil, nil, nil },
        { 2962, "A", 20, 30, "Ozzie Togglevolt", "Dun Morogh - Kharanos 45,49", "The Only Cure is More Green Glow", false, {2926}, nil, "Collect High-Efficiency Irradiated Dust in Gnomeregan (highly unstable, it decays quickly) and return the Heavy Lead Vial to Ozzie as well.", "Sampling method: use the Heavy Lead Vial on living Irradiated Oozes, Irradiated Creepers or Irradiated Water Elementals.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9365, 9364}, nil, 1268, "Ozzie Togglevolt", { xp = 2450, money = 2500 } },
        { 2904, nil, 24, 30, "Kernobee", "Gnomeregan", nil, true, nil, {9535, 9536, 270042}, "Escort Kernobee to the exit, then report back to Scooty in Booty Bay.", "Escort quest. Scooty (Stranglethorn Vale - Booty Bay 27,77). The escort ends at the dungeon's front gate (just reach the door, no need to go out); the little gnome doesn't pull mobs, so stealth classes can stay stealthed throughout.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 7850, "Kernobee", { xp = 2450 } },
        { 2924, "A", 24, 30, "Klockmort Spannerspan", "Ironforge - Tinker Town 68,46", "Essential Artificials", false, {2925}, nil, "Collect 12 Basic Modules and bring them to Klockmort Spannerspan in Ironforge.", "The prerequisite can be taken from Mathiel (Darnassus - Warrior's Terrace 59,45). Any enemy in Gnomeregan can drop it.", {{24,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9278}, nil, 6169, "Klockmort Spannerspan", { xp = 3050, money = 5500, rep = { {54, 150, "Gnomeregan Exiles"} } } },
        { 2841, "H", 25, 35, "Nogg", "Orgrimmar - Valley of Honor 75,25", nil, false, nil, {9623, 9624, 9625}, "Retrieve the drilling rig blueprints and the combination to Mekgineer's Safe from Gnomeregan and bring them to Nogg in Orgrimmar.", "Mekgineer Thermaplugg is the final boss of Gnomeregan. During the fight, remember to press the button beside him to stop him throwing bombs.", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, {9153, 9299}, nil, 3412, "Nogg", { xp = 2750, rep = { {76, 100, "Orgrimmar"} } } },
        { 2929, "A", 25, 35, "High Tinker Mekkatorque", "Ironforge - Tinker Town 68,48", nil, false, nil, {9623, 9624, 9625}, "Enter Gnomeregan and kill Mekgineer Thermaplugg, then report to High Tinker Mekkatorque.", "He is the final boss. During the fight, press the button beside him to stop him throwing bombs.", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7937, "High Tinker Mekkatorque", { xp = 2750, money = 3500, rep = { {54, 100, "Gnomeregan Exiles"} } } },
        { 2930, "A", 25, 30, "Master Mechanic Castpipe", "Ironforge - Tinker Town 69,48", "Data Rescue", false, {2931}, {9605, 9604}, "Bring the Colorful Punch Cards to Master Mechanic Castpipe in Ironforge.", "The prerequisite can be taken from Gaxim Rustfizzle (Stonetalon Mountains 59,67), but it's not required. Punch card relay: the White Punch Card comes from roaming elites on the upper level outside the dungeon — insert it into the card reader outside the dungeon. Each reader gives the card needed for the next one; grab the Techbot's brain along the way.", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9316}, nil, 7950, "Master Mechanic Castpipe", { xp = 3650, money = 2500, rep = { {54, 200, "Gnomeregan Exiles"} } } },
        { 2951, nil, 25, 30, "Super Cleaner 5200", "Gnomeregan - Clean Zone", nil, true, nil, nil, "Put grimy items into the Super Cleaner 5200, insert three silver coins to start the machine.", "This quest is repeatable with all \"grimy\" items.", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9308}, nil, nil, nil, { xp = 2450, money = 300 } },
        { 2952, nil, 25, 30, "Super Cleaner 5200", nil, nil, true, {2951}, {9363}, nil, nil, {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, nil, nil, { xp = 2450 } },
        { 2945, nil, 28, 34, "Return of the Ring", "Random drop in Gnomeregan", nil, true, nil, nil, "Figure out how to get the Grimy Ring cleaned.", "Just clean it with the Super Cleaner 5200 — the machine is inside the dungeon.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9326}, nil, nil, nil, { xp = 2700, money = 300 } },
        { 2947, "A", 28, 34, "Return of the Ring", "Obtained by cleaning the Grimy Ring", "Return of the Ring", true, {2945}, nil, "You may keep the ring, or find its owner by the name engraved inside.", "Turn in to Talvash del Kissel (Ironforge - The Mystic Ward 36,3). The reward ring has random stats.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9362}, nil, nil, nil, { xp = 2700 } },
        { 2949, "H", 28, 34, "Return of the Ring", "Obtained by cleaning the Grimy Ring", "Return of the Ring", true, {2945}, nil, "You may keep the ring, or find its owner by the name engraved inside.", "Turn in to Nogg (Orgrimmar - Valley of Honor 75,25). The reward ring has random stats.", {{28,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {9362}, nil, nil, nil, { xp = 2700 } },
    },
    ["razorfen_kraul"] = {
        { 6522, "H", 28, 36, "Starts from the item [Small Scroll]", nil, nil, true, nil, nil, "Bring the 'Small Scroll' to Bragor Bloodfist in the Undercity Royal Quarter.", "The 'Small Scroll' drops from Razorfen Kraul's final boss Charlga Razorflank (about 45%); looting it starts this quest. The chain continues in Razorfen Downs: Bragun Bloodfist continues with 'An Unholy Alliance' — kill Ambassador Malcin in the clearing before the dungeon and bring his head to Varimathras in the Undercity.", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17008}, nil, nil, nil, { xp = 2800, money = 4000 } },
        { 1221, nil, 20, 26, "Mebok Mizzyrix", "The Barrens - Ratchet 62,37", nil, false, nil, {6755}, "Gather the Opened Chest, the Gopher Cane and the \"Gopher Command Manual\"; use the chest in Razorfen Kraul to summon the gopher and make it sniff out the Blueleaf Tubers; finally bring the cane, the chest and 10 Blueleaf Tubers to Mebok Mizzyrix in Ratchet.", "Both the chest and the manual can be found near Mebok Mizzyrix.", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {5876, 5880, 5897, 6684}, nil, 3446, "Mebok Mizzyrix", { xp = 2100, rep = { {470, 100, "Ratchet"} } } },
        { 1701, "A", 20, nil, "Furen Longbeard", "Stormwind City - Dwarven District 64,37", "Fire Hardened Mail", false, {1702}, nil, "Gather the specified materials for Frun Longbeard in Stormwind City.", "Warrior only! The phosphorus comes from Roogug; Scorched Spider Fangs from Wetlands spiders, and Charred and Sleek Chimera Horns from chimera cubs and females in Stonetalon Mountains. Roogug location: take the first left inside the dungeon, follow the curve over the vine bridge — he is right there on the other side.", {{20,1}, {24,2}, {26,3}, {31,4}, {36,5}}, {6838, 6839, 6840, 6841, 6842}, "Warrior", 5413, "Furen Longbeard", { xp = 2300 } },
        { 1838, "H", 20, nil, "Thun'grim Firegaze", "The Barrens 57,30", "Brutal Armor", false, {1824}, nil, "Collect 15 Smoky Iron Ingots, 10 Azurite Powders, 10 Iron Bars and 1 vial of Phlogiston for Thorngrimr.", "Warrior only! Phlogiston comes from Rukhug. After turning in, he will offer the follow-up quest.", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {7126, 7127, 3575, 6841, 7587}, "Warrior", 5878, "Thun'grim Firegaze", { xp = 3650 } },
        { 1144, nil, 23, 30, "Willix the Importer", "Razorfen Kraul", nil, true, nil, {6748, 6750, 6749, 274078}, "Escort Willix the Importer out of Razorfen Kraul.", "The escort fails if you get too far ahead of him or fall too far behind. Turn right from the entrance through the boar area to reach Willix — no bosses need to be cleared.", {{22,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 4508, "Willix the Importer", { xp = 7250, rep = { {470, 150, "Ratchet"} } } },
        { 1142, "A", 25, 30, "Heralath Fallowbrook", "Razorfen Kraul", nil, true, nil, {6751, 6752, 270047}, "Retrieve Thalara's Pendant and return it to Thalara Fallowbrook in Darnassus.", "The pendant is a random drop. Turn in to Thalara Fallowbrook (Darnassus - Tradesmen's Terrace 69,67).", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {5825}, nil, 4510, "Heralath Fallowbrook", { xp = 3050, rep = { {69, 150, "Darnassus"} } } },
        { 1101, "A", 29, 34, "Falfindel Waywarder", "Feralas - Sarannar 89,46", "The Crone of the Kraul", false, {1100}, {4197, 6742, 6725, 274084}, "Bring Calgar Spinegouge's badge to Falfindel Waywarder in Sarannar.", "The badge drops from Calgar Spinegouge.", {{29,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {5792}, nil, 4048, "Falfindel Waywarder", { xp = 3350 } },
        { 1102, "H", 29, 34, "Auld Stonespire", "Thunder Bluff 36,59", nil, false, nil, {4197, 6742, 6725, 274084}, "Bring Calgar Spinegouge's heart to Auld Stonespire in Thunder Bluff.", "Calgar Spinegouge is inside the dungeon.", {{29,1}, {30,2}, {32,3}, {37,4}, {43,5}}, {5793}, nil, 4451, "Auld Stonespire", { xp = 8500, rep = { {81, 200, "Thunder Bluff"} } } },
        { 1109, "H", 30, 33, "Master Apothecary Faranell", "Undercity - The Apothecarium 48,69", nil, false, nil, nil, "Collect a sample of Marsh Bat guano for Master Apothecary Faranell of the Undercity.", "Only the Kraul Bats in the far-west chamber (just before the last boss, Charlga Razorflank) drop the guano — with a very high drop rate — and you must fight through most of the dungeon to reach them.", {{30,2}, {31,3}, {36,4}, {42,5}}, {5801}, nil, 2055, "Master Apothecary Faranell", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
        { 79360, "H", 30, 33, "Rau Cliffrunner", "Thousand Needles", nil, false, {96136}, nil, "Enter Razorfen Kraul, retrieve the \"Tattered Notes\" - proof of the quilboar twisting the elements - and bring them to Rau Cliffrunner.", "Shaman only (Orc/Tauren/Troll): Orcs and Trolls accept from Rau Cliffrunner, Tauren from Prate Whitecloud; turn-in depends on race (Rau Cliffrunner or Bath'rah the Windwatcher). Step 1 of the shaman totem chain, followed by 'Look to the Sky', 'Storm, Earth and Fire', 'Heed My Call' and 'Storm Weapon'.", {{30,1}, {31,2}, {36,3}, {42,4}}, {274463}, "Shaman", 4722, "Rau Cliffrunner", { xp = 6950 } },
        { 96264, "A", 30, 33, "Verik Thunderhowl", "Arathi Highlands 59.8,27.6", nil, false, {94789}, nil, "Enter Razorfen Kraul, retrieve the \"Tattered Notes\" - proof of the quilboar twisting the elements - and bring them to Veyric Thunderhowl in Arathi Highlands.", "Shaman-only (Alliance only): step 1 of the shaman totem chain, followed in order by \"Gaze to the Sky\", \"Storm, Earth and Fire\", \"Heed My Call\" and \"Storm Weapon\".", {{30,1}, {31,2}, {36,3}, {42,4}}, {274463}, "Shaman", 259023, "Verik Thunderhowl", { xp = 6950 } },
    },
    ["sm_graveyard"] = {

        { 1051, "H", 25, 33, "Vorrel Sengutz", "Scarlet Monastery - Graveyard", nil, true, nil, {7750, 4643, 7751}, "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", "The ring is on Vorrel Sengutz at the front of the Scarlet Monastery Graveyard; Nancy (Alterac Mountains 31,32) also holds a quest-related item.", {{25,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {5538}, nil, 3981, "Vorrel Sengutz", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
        { 1160, "H", 25, 36, "Parqual Fintallas", "Undercity - The Apothecarium 57,65", "Test of Lore", false, {1159}, nil, "Recover \"The Origins of the Undead\" and bring it to Parqual Fintallas in the Undercity.", "The series starts with Dorn Plainstalker (Thousand Needles 53,41). The book is in the Scarlet Monastery Library: on the table in the first room on the left after entering the Gallery of Treasures (the open book).", {{25,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {5861}, nil, 4488, "Parqual Fintallas", { xp = 2100, rep = { {68, 75, "Undercity"} } } },
        { 1049, "H", 28, 38, "Sage Truthseeker", "Thunder Bluff 34,47", nil, false, nil, {7747, 17508, 7749}, "Retrieve \"Compendium of the Fallen\" from the Scarlet Monastery and bring it to Sage Truthseeker in Thunder Bluff.", "The book is in the Library area. The Forsaken cannot take this quest for story reasons.", {{28,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {5535}, nil, 3978, "Sage Truthseeker", { xp = 3550, rep = { {81, 150, "Thunder Bluff"} } } },
        { 1050, "A", 28, 38, "Librarian Mae Paledust", "Ironforge - Hall of Explorers 74,12", nil, false, nil, {7746}, "Retrieve \"Mythology of the Titans\" from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", "The book is on the floor of the left corridor, before Arcanist Doan's room in the Library.", {{28,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {5536}, nil, 3979, "Librarian Mae Paledust", { xp = 3550, rep = { {47, 150, "Ironforge"} } } },
        { 1113, "H", 30, 33, "Master Apothecary Faranell", "Undercity - The Apothecarium 48,69", "Hearts of Zeal", false, {1109}, nil, "Collect 20 Hearts of Zeal for Master Apothecary Faranell of the Undercity.", "Every mob in the Scarlet Monastery has a chance to drop them.", {{30,2}, {31,3}, {36,4}, {42,5}}, {5805}, nil, 2055, "Master Apothecary Faranell", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
        { 1951, nil, 30, nil, "Tabetha", "Dustwallow Marsh 43,57", "Rituals of Power", false, {1950}, nil, "Bring \"Rituals of Power\" to Tabetha in Dustwallow Marsh.", "Mage class quest. The book is in the Scarlet Monastery Library, on the floor of the left corridor before Arcanist Doan's room.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {7274}, "Mage", 6548, "Magus Tirth", nil },
        { 96800, "A", 30, 38, "Magus Olvek", "Alterac Mountains 9.8,63", nil, false, nil, {276898, 276899}, "Retrieve \"The Lost Magic of the Runemasters\" from the Scarlet Monastery and bring it to Magus Olvek in the Alterac Mountains.", "The book is on the table on the right side of Arcanist Doan's chamber, the last boss of the Library — it's the red book.", {{30,1}, {34,2}, {36,3}, {41,4}, {48,5}}, {273169}, nil, 264265, "Magus Olvek", { xp = 2850, money = 4500, rep = { {2740, 100, "Kirin Tor"} } } },
        { 1048, "H", 33, 42, "Varimathras", "Undercity - Royal Quarter 56,92", nil, false, nil, {6802, 6803, 10711}, "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod the Champion and Houndmaster Loksey, then report back to Varimathras in the Undercity.", "Whitemane and Mograine are in the Cathedral, Herod in the Armory, Loksey in the Library.", {{33,1}, {38,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 2425, "Varimathras", { xp = 5150, rep = { {68, 200, "Undercity"} } } },
        { 1053, "A", 34, 40, "Raleigh the Devout", "Hillsbrad Foothills - Southshore 51,58", "In the Name of the Light", false, {1052}, {6829, 6830, 6831, 11262}, "Kill High Inquisitor Whitemane, Commander Mograine, Herod the Champion and Houndmaster Loksey, then report back to Raleigh the Devout in Southshore.", "The series starts with Brother Crowley (Stormwind - Cathedral 52,43); you can also take it directly from the Scarlet Crusade emissary at Nijel's Point in Desolace. Three target locations: Cathedral (Whitemane, Mograine), Armory (Herod), Library (Loksey).", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 3980, "Raleigh the Devout", { xp = 4700, rep = { {72, 200, "Stormwind City"} } } },
    },
