    ["the_drowned_city"] = {
        { 95775, "H", 30, 40, "Kenvere", "Stranglethorn Vale - Grom'gol Base Camp 32.3,27.7", nil, false, {95770}, nil, "Use the hide and charcoal to make a rubbing of the stone tablet in the Sunken City.", "All three prerequisites are with Kin'weelay at Grom'gol Base Camp: The Vile Reef → Ancient Gurubashi Legends → Locate the Lost City.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270308, 270309, 270310, 270311}, nil, 2519, "Kenvere", { xp = 8450, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 95776, "H", 30, 38, "Commander Agrogosh", "Stranglethorn Vale - Grom'gol Base Camp 32.2,28.9", nil, false, {95773}, {279888, 279889}, "Destroy Val'taka in the Sunken City.", "Kill target: Varthak, boss of the dungeon's 2nd area; the prerequisite is \"Enemies in the Water\" from Commander Agrogosh at Grom'gol Base Camp.", {{30,1}, {34,2}, {36,3}, {41,4}, {47,5}}, nil, nil, 2464, "Commander Agrogosh", { xp = 9500, rep = { {530, 100, "Darkspear Trolls"}, {76, 100, "Orgrimmar"} } } },
        { 95787, "A", 30, 40, "Loremaster Dibbs", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95786}, nil, "Use the hide and charcoal to make a rubbing of the stone tablet in the Sunken City.", "Prerequisite 'Troll Witchery': after completing Brother Nimetz's 'Troll Witchery' in Stranglethorn Vale (turning in the shoddy troll idol), you can accept this quest from Loremaster Dibbs. Once the rubbings are done, return to Dibbs, who translates them and forwards them to Ironforge. The four tablets are spread across the dungeon: down the slope on the left after boss 1, in the skull pile in the pirate area, at the naga boss, and at the final boss — take the rubbing as soon as you see each one instead of leaving it for the end.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270308, 270309, 270310, 270311}, nil, 2277, "Loremaster Dibbs", { xp = 8450, rep = { {72, 100, "Stormwind City"} } } },
        { 95788, "A", 30, 40, "Loremaster Dibbs", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95786}, nil, "Collect 5 I'lalai Idols from the trolls in the Sunken City.", "Prerequisite \"Troll Witchery\": paired with \"Take Two with Water\" from Loremaster Dibbs; available after completing Brother Nimetz's \"Troll Witchery\" in Stranglethorn Vale.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270343}, nil, 2277, "Loremaster Dibbs", { xp = 8450, rep = { {72, 100, "Stormwind City"} } } },
        { 96774, "H", 30, 40, "Mazu'kon", "Mulgore 32.5,20.7", nil, false, nil, nil, "Retrieve the Ancient Gurubashi Idol from \"the most stylish priest\" in the Sunken City and bring it to Mazukon in Mulgore.", "Starts outside the dungeon (Mulgore 32.5,20.7, possibly Thunder Bluff); Mazukon starts and ends it at the same place. The idol drops from the Undying Marrow in the final boss area (the same item as the Alliance 'Ancient Gurubashi Secrets'); keep an eye on the priests along the way too.", {{30,1}, {36,2}, {38,3}, {43,4}, {51,5}}, {276894}, nil, 264074, "Mazu'kon", { xp = 8800, money = 10000, rep = { {530, 150, "Darkspear Trolls"} } } },
        { 95789, nil, 34, 40, "Krazek", "Stranglethorn Vale - Booty Bay 27.0,77.2", nil, false, nil, {279882, 279930}, "Collect 10 Voodoo-Infused Artifacts and bring them to Krazek in Booty Bay.", "Starts outside the instance (Booty Bay); the artifacts drop from Brine Seer casters inside the dungeon, so watch your loot while clearing; available to both factions.", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270333}, nil, 773, "Krazek", { xp = 10450, rep = { {21, 100, "Booty Bay"}, {470, 50, "Ratchet"}, {369, 50, "Gadgetzan"} } }},
        { 95791, nil, 34, 40, "Krazek", "Stranglethorn Vale - Booty Bay 27.0,77.2", nil, false, nil, {279883, 279884}, "Kill Captain Dreadless and the Brineseer Coroner, then report back to Krazek in Booty Bay.", "Kill targets: the captain is one of the dungeon bosses; the coroners come in groups along the way and can be done in one pass; both factions can take it.", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 773, "Krazek", { xp = 10450, rep = { {21, 100, "Booty Bay"}, {369, 50, "Gadgetzan"}, {577, 50, "Everlook"} } }},
        { 97130, "A", 34, 40, "Archmage Timmel", "Alterac Mountains 15.4,73.8", nil, false, nil, nil, "Retrieve the Ancient Gurubashi Idol and bring it to Archmage Timmel of the Kirin Tor.", "Starts outside the instance (Alterac Mountains); the idol drops from the Undying Marrow fight and is the same quest item as the Horde's Gurubashi Idol quest.", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {276894}, nil, 31439, "Archmage Timmel", { xp = 10450, rep = { {2740, 300, "Kirin Tor"}, {72, 150, "Stormwind City"} } }},
        { 95798, "A", 30, 40, "Loremaster Dibbs", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95788}, {279879, 279878}, "Bring the I'lalai Idols to Abra Cadabra, the wand vendor in Dalaran.", "Prerequisite \"Magic of the Sunken City\": the I'lalai idol collected in \"Magic of the Sunken City\" is exactly this quest's turn-in item, and the quest giver is that quest's turn-in NPC; cannot be shared.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {270343}, nil, 2277, "Loremaster Dibbs", { xp = 2350, rep = { {72, 75, "Stormwind City"} } } },
        { 95799, "A", 30, 40, "Loremaster Dibbs", "Hillsbrad Foothills - Southshore 50.6,57.1", nil, false, {95787}, {279880, 279881}, "Take the \"Legends of I'lalai\" translated by Lorekeeper Dibbs to Historian Karnik in Ironforge.", "Prerequisite \"Take Two with Water\": the result of the rubbing quest (the translated I'lalai legend) is this quest's turn-in item; the quest giver is Lorekeeper Dibbs (Explorers' League), and the turn-in is Historian Karnik in Ironforge.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {272124}, nil, 2277, "Loremaster Dibbs", { xp = 2350, rep = { {72, 75, "Stormwind City"}, {47, 50, "Ironforge"} } } },
    },
    ["sm_armory"] = {

        { 1051, "H", 25, 33, "Vorrel Sengutz", "Scarlet Monastery - Graveyard", nil, true, nil, {7750, 4643, 7751}, "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", "The ring is on Vorrel Sengutz at the front of the Scarlet Monastery Graveyard; Nancy (Alterac Mountains 31,32) also holds a quest-related item.", {{25,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {5538}, nil, 3981, "Vorrel Sengutz", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
        { 1160, "H", 25, 36, "Parqual Fintallas", "Undercity - The Apothecarium 57,65", "Test of Lore", false, {1159}, nil, "Recover \"The Origins of the Undead\" and bring it to Parqual Fintallas in the Undercity.", "The series starts with Dorn Plainstalker (Thousand Needles 53,41). The book is in the Scarlet Monastery Library: on the table in the first room on the left after entering the Gallery of Treasures (the open book).", {{25,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {5861}, nil, 4488, "Parqual Fintallas", { xp = 2100, rep = { {68, 75, "Undercity"} } } },
        { 1049, "H", 28, 38, "Sage Truthseeker", "Thunder Bluff 34,47", nil, false, nil, {7747, 17508, 7749}, "Retrieve \"Compendium of the Fallen\" from the Scarlet Monastery and bring it to Sage Truthseeker in Thunder Bluff.", "The book is in the Library area. The Forsaken cannot take this quest for story reasons.", {{28,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {5535}, nil, 3978, "Sage Truthseeker", { xp = 3550, rep = { {81, 150, "Thunder Bluff"} } } },
        { 1050, "A", 28, 38, "Librarian Mae Paledust", "Ironforge - Hall of Explorers 74,12", nil, false, nil, {7746}, "Retrieve \"Mythology of the Titans\" from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", "The book is on the floor of the left corridor, before Arcanist Doan's room in the Library.", {{28,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {5536}, nil, 3979, "Librarian Mae Paledust", { xp = 3550, rep = { {47, 150, "Ironforge"} } } },
        { 1113, "H", 30, 33, "Master Apothecary Faranell", "Undercity - The Apothecarium 48,69", "Hearts of Zeal", false, {1109}, nil, "Collect 20 Hearts of Zeal for Master Apothecary Faranell of the Undercity.", "Every mob in the Scarlet Monastery has a chance to drop them.", {{30,2}, {31,3}, {36,4}, {42,5}}, {5805}, nil, 2055, "Master Apothecary Faranell", { xp = 3300, rep = { {68, 150, "Undercity"} } } },
        { 1951, nil, 30, nil, "Tabetha", "Dustwallow Marsh 43,57", "Rituals of Power", false, {1950}, nil, "Bring \"Rituals of Power\" to Tabetha in Dustwallow Marsh.", "Mage class quest. The book is in the Scarlet Monastery Library, on the floor of the left corridor before Arcanist Doan's room.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {7274}, "Mage", 6548, "Magus Tirth", nil },
        { 96800, "A", 30, 38, "Magus Olvek", "Alterac Mountains 9.8,63", nil, false, nil, {276898, 276899}, "Retrieve \"The Lost Magic of the Runemasters\" from the Scarlet Monastery and bring it to Magus Olvek in the Alterac Mountains.", "The book is on the table on the right side of Arcanist Doan's chamber, the last boss of the Library — it's the red book.", {{30,1}, {34,2}, {36,3}, {41,4}, {48,5}}, {273169}, nil, 264265, "Magus Olvek", { xp = 2850, money = 4500, rep = { {2740, 100, "Kirin Tor"} } } },
        { 1048, "H", 33, 42, "Varimathras", "Undercity - Royal Quarter 56,92", nil, false, nil, {6802, 6803, 10711}, "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod the Champion and Houndmaster Loksey, then report back to Varimathras in the Undercity.", "Whitemane and Mograine are in the Cathedral, Herod in the Armory, Loksey in the Library.", {{33,1}, {38,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 2425, "Varimathras", { xp = 5150, rep = { {68, 200, "Undercity"} } } },
        { 1053, "A", 34, 40, "Raleigh the Devout", "Hillsbrad Foothills - Southshore 51,58", "In the Name of the Light", false, {1052}, {6829, 6830, 6831, 11262}, "Kill High Inquisitor Whitemane, Commander Mograine, Herod the Champion and Houndmaster Loksey, then report back to Raleigh the Devout in Southshore.", "The series starts with Brother Crowley (Stormwind - Cathedral 52,43); you can also take it directly from the Scarlet Crusade emissary at Nijel's Point in Desolace. Three target locations: Cathedral (Whitemane, Mograine), Armory (Herod), Library (Loksey).", {{34,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 3980, "Raleigh the Devout", { xp = 4700, rep = { {72, 200, "Stormwind City"} } } },
