    ["razorfen_downs"] = {
        { 6521, "H", 28, 36, "Varimathras", "Undercity - Royal Quarter 56,92", "An Unholy Alliance", false, {6522}, {17039, 17042, 17043}, "Bring Ambassador Marquin's head to Varimathras in the Undercity.", "The prerequisite is given by the final boss of Razorfen Kraul. Ambassador Malcin is in the clearing before the instance (The Barrens - Razorfen Downs 48,92).", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17009}, nil, 2425, "Varimathras", { xp = 3500, money = 2000 } },
        { 6522, "H", 28, 36, "Starts from the item [Small Scroll]", nil, nil, true, nil, nil, "Bring the 'Small Scroll' to Bragor Bloodfist in the Undercity Royal Quarter.", "The 'Small Scroll' drops from Razorfen Kraul's final boss Charlga Razorflank (about 45%); looting it starts this quest. The chain continues in Razorfen Downs: Bragun Bloodfist continues with 'An Unholy Alliance' — kill Ambassador Malcin in the clearing before the dungeon and bring his head to Varimathras in the Undercity.", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17008}, nil, nil, nil, { xp = 2800, money = 4000 } },
        { 6626, nil, 28, 35, "Myriam Moonsinger", "The Barrens - Razorfen Downs 49,94", nil, false, nil, nil, "Kill 8 Razorfen Guardians, 8 Razorfen Weavers and 8 Death Cultists, then report to Myriam Moonsinger at the Razorfen Downs entrance.", "All three of these mobs are on the path you take before entering the dungeon.", {{28,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 12866, "Myriam Moonsinger", { xp = 3450, money = 7500 } },
        { 3523, nil, 32, 37, "Belnistrasz", nil, nil, true, nil, nil, nil, "This is not the escort quest itself — complete this one first, and only then the real escort quest 'Extinguishing the Idol' becomes available. Make sure EVERYONE in the party finishes this quest before starting the escort segment, or those who haven't will miss the follow-up.", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, {10682}, nil, 8516, "Belnistrasz", { xp = 285 } },
        { 3525, nil, 32, 37, "Belnistrasz", "Razorfen Downs", "Extinguishing the Idol", true, {3523}, {10710}, "Accompany Belnistrasz to the quillboar idol in Razorfen Downs and protect him while his ritual seals it.", "Once you agree to help, waves of mobs will attack him throughout the ritual — keep him alive; when it is done, turn the quest in at the idol for the reward.", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, nil, nil, 8516, "Belnistrasz", { xp = 4250 } },
        { 3341, "H", 37, 42, "Andrew Brownell", "Undercity - Magic Quarter 72,32", nil, false, nil, {10823, 10824}, "Kill Amnennar the Coldbringer for Andrew Brownell and bring back his skull.", "Amnennar the Coldbringer is the final boss of Razorfen Downs.", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {10420}, nil, 2308, "Andrew Brownell", { xp = 4300, rep = { {68, 150, "Undercity"} } } },
        { 3636, "A", 39, 42, "Archbishop Benedictus", "Stormwind City - Cathedral of Light 50,45", nil, false, nil, {10823, 10824}, "Kill Amnennar the Coldbringer of Razorfen Downs for Archbishop Benedictus.", "He is the final boss of Razorfen Downs. ★ This quest cannot be shared — everyone in the party must pick it up for themselves.", {{39,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 1284, "Archbishop Benedictus", { xp = 4300, rep = { {72, 150, "Stormwind City"} } } },
        { 96773, "A", 34, 41, "Archmage Landalock", "Alterac Mountains 15.4,73.8", nil, false, nil, nil, "Retrieve the Eye of Rimewind and bring it to Archmage Landalock of the Kirin Tor.", "Starts outside the dungeon (Alterac Mountains); the Eye of Coldwind drops from a dungeon boss - watch the loot after the final boss.", {{34,1}, {37,2}, {39,3}, {44,4}, {51,5}}, {276916}, nil, 20735, "Archmage Landalock", { xp = 8600, money = 5500, rep = { {2740, 300, "Kirin Tor"}, {72, 150, "Stormwind City"} } }},
        { 97196, "H", 34, 41, "Sutara Plainstalker", "Mulgore 34.6,23.0", nil, false, nil, nil, "Retrieve the Eye of Rimewind and bring it to Sutara Plainstalker.", "Picked up from and turned in to Sutura Plainswalker (Mulgore 34.6,23.0); the Eye of Biting Wind drops from a dungeon boss, watch your loot after the final boss.", {{34,1}, {37,2}, {39,3}, {44,4}, {51,5}}, {276916}, nil, 264078, "Sutara Plainstalker", { xp = 8600, rep = { { 2787, 300, "Earthen Ring" }, { 81, 150, "Thunder Bluff" } } } },
        { 93604, nil, 35, 45, "Cogswug the Brave", "Desolace - Bristleback Refuge 72.5,31.5", nil, false, {93601}, {260237}, "Delve into Razorfen Downs, retrieve the \"Venomous Blood of Agamaggan\" and bring it to Kogsug the Brave at Spikeback Refuge in Desolace.", "Step 4 of the Shen'dralar treant series; the first 3 steps start with the treant in the Forgotten Garden of Shen'dralar (new zone in the southeast corner of Desolace). Kogsug is the nomadic Bristleback chieftain of Bristleback Refuge (level 43 elite, 72.5,31.5). The Venomous Blood of Agamaggan is on the spiral path leading to the final boss: in one of the tents there's a big bright red cauldron — stand next to it and click to summon an ooze; kill it to loot the blood. Kogsug specifically stressed that the batch from Razorfen Kraul won't fool him.", {{35,1}, {38,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 253527, "Cogswug the Brave", { xp = 10200, money = 6500 } },
    },
