        { 7501, "A", 54, 60, "The Power of the Light", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18472}, "Turn this tome in to its owner.", "Paladin class trinket quest. Bring it to Lorekeeper Mykos (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18359}, "Paladin", nil, nil, { xp = 6600, rep = { {809, 200, "Shen'dralar"} } } },
        { 7502, nil, 54, 60, "You and Frost Shock", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18467}, "Turn this tome in to its owner.", "Shaman class trinket quest. Bring it to Lorekeeper Yavo (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18360}, "Warlock", nil, nil, { xp = 6600, rep = { {809, 200, "Shen'dralar"} } } },
        { 7503, nil, 54, 60, "The Greatest Hunter", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18473}, "Turn this tome in to its owner.", "Hunter class trinket quest. Bring it to Lorekeeper Mykos (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18361}, "Hunter", nil, nil, { xp = 6600, rep = { {809, 200, "Shen'dralar"} } } },
        { 7504, nil, 54, 60, "What the Light Never Tells You", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18469}, "Turn this tome in to its owner.", "Priest class trinket quest. Bring it to Lorekeeper Yavo (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18362}, "Priest", nil, nil, { xp = 6600, rep = { {809, 200, "Shen'dralar"} } } },
        { 7505, "H", 54, 60, "The Power of the Light", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18471}, "Turn this tome in to its owner.", "Paladin class trinket quest. Bring it to Lorekeeper Mykos (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18363}, "Shaman", nil, nil, { xp = 6600, rep = { {809, 200, "Shen'dralar"} } } },
        { 7506, nil, 54, 60, "The Emerald Dream", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18470}, "Turn this tome in to its owner.", "Druid class trinket quest. Bring it to Lorekeeper Yavo (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18364}, "Druid", nil, nil, { xp = 6600, money = 100, rep = { {809, 200, "Shen'dralar"} } } },
        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "Doable in one run. Recommended route: North first (tribute run — bring the ogre-suit materials and the broken trap) → West (kill Immol'thar) → Library (kill Prince Tortheldrin) → back to North, turn in to Fengus on the way out.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 5526, nil, 56, nil, "Rabine Saturna", "Moonglade 51,44", "Shards of the Felvine", false, {5527}, { 18535, 18536 }, "Find the warped vine in Dire Maul and collect a fragment (you must kill Ozien first), seal it with the Purification Cask, and bring it to Rabine Saturna at Nighthaven in Moonglade.", "Ozien is in Dire Maul East. Reliquary of Purity (Silithus 62,54). The prerequisite also comes from Rabine Saturna.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18540, 18539}, nil, 11801, "Rabine Saturna", { xp = 8300, rep = { { 609, 150, "[UNUSED] Brother Milius" } } } },
        { 7462, "A", 56, 60, "Shen'dralar Ancient", nil, "The Treasure of the Shen'dralar", true, {7461}, {18420, 18421, 18424}, nil, nil, {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, nil, { xp = 660, money = 27000 }},
        { 7877, "H", 56, 60, "Shen'dralar Ancient", "Dire Maul: West (upper level)", "The Treasure of the Shen'dralar", true, {7461}, {18420, 18421, 18424}, "Return to the Library to find the Shen'dralar treasure and claim your reward!", "The treasure is under the ladder in the Library.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "Shen'dralar Ancient", { xp = 660, money = 27000 } },
        { 5528, nil, 57, 60, "Trampler Craig", "Dire Maul: North,", nil, true, nil, {18269, 18284}, "Get free booze.", "Talk to Stomper Kreeg to accept and turn in at the same time; you must have the \"It's Good to Be King\" buff.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14322, "Trampler Craig", nil },
        { 8948, nil, 58, 60, "Anthion Harmon", "Eastern Plaguelands", "Anthion's Strange Request", false, {8947}, nil, nil, nil, {{58,3}, {63,4}, {72,5}}, {21983}, nil, 16016, "Anthion Harmon", { xp = 6600 } },
        { 8949, nil, 58, 60, "Falrin Treeshaper", nil, nil, true, {8948}, {22150, 22149}, nil, "Ogre Warbead drop rates: about 1/10 in Dire Maul North, 1/7 in LBRS (but far fewer ogres there), 1/50 outside the DM arena.", {{58,3}, {63,4}, {72,5}}, {21982}, nil, 16032, "Falrin Treeshaper", { xp = 6600 } },
        { 8950, nil, 58, 60, "Falrin Treeshaper", "Dire Maul", nil, true, {8949}, nil, nil, "The shadow essence drops from the ghosts in Dire Maul West.", {{58,3}, {63,4}, {72,5}}, {22224, 20520, 14344}, nil, 16032, "Falrin Treeshaper", { xp = 6600 } },
        { 8967, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "Vital Materials", false, {8963}, nil, "Use the summoning brazier to call out Isalien's spirit and kill her; return the brazier and the left half of the Vatalak Trinket to Bodley.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Isalien is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22050}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8990, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8985}, nil, "Use the summoning brazier to call out Isalien's spirit and kill it; return the brazier and Duke Vatalak's trinket to Bodley.", "You need the Extraplanar Ghost Revealer to see Bodley (from \"Finding Anthion\"). Isalien is summoned inside the instance.", {{58,3}, {63,4}, {72,5}}, {22048, 22050}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7463, nil, 60, 60, "Lorekeeper Lydros", nil, nil, true, nil, { 10140 }, nil, nil, {{60,3}, {63,4}, {72,5}}, {18299}, "Mage", 14368, "Lorekeeper Lydros", { xp = 6600, rep = { {809, 200, "Shen'dralar"} } } },
        { 7507, nil, 60, 60, "Lorekeeper Lydros", "Dire Maul: West, the Library", nil, false, nil, nil, "Hand the Libram of Rapidity, 1 Primal Black Diamond, 2 Large Brilliant Shards and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul for a Quickening Elixir.", "No prerequisite, but the \"Elven Legends\" quest must be completed first. The libram drops randomly and is tradeable. Blood of Heroes spawns randomly on the ground in the Eastern and Western Plaguelands, picked up bound.", {{60,3}, {63,4}, {72,5}}, {18401}, nil, 14368, nil, { xp = 9950, rep = { {809, 200, "Shen'dralar"} } }},
        { 7508, nil, 60, 60, "Starts from the item [Dull and Flat Elven Blade]", nil, nil, true, {7507}, nil, nil, "'Foror's Compendium of Dragon Slaying' (drops in Dire Maul, tradeable) triggers the Quel'Serrar quest chain: hand the book to the lorekeeper in the Dire Maul West library to receive the 'Dull and Flat Elven Blade' and begin this epic weapon quest.", {{60,3}, {63,4}, {72,5}}, {18513}, nil, nil, nil, { xp = 9950 } },
        { 7581, nil, 60, nil, "Daio the Decrepit", "Blasted Lands - The Tainted Scar 34,50", nil, false, nil, nil, "Go to the Warpwood Quarter of Dire Maul, take 15 Satyr Blood from the wild satyrs, and bring them to the withered Dio of the Tainted Scar.", "The warlock Doomguard summoning quest line; all related quests are picked up from Daio the Decrepit. Entering Dire Maul East through the \"back door\" is easiest (Feralas - The Lariss Pavilion 77,37), which needs the Crescent Key.", {{60,3}, {63,4}, {72,5}}, {18603}, "Warlock", 14463, "Daio the Decrepit", { xp = 6600 } },
    },
    ["lower_blackrock_spire"] = {
        { 4788, nil, 40, 58, "Prospector Ironboot", "Tanaris - Steamwheedle Port 66,23", "The Final Tablets", false, {5065}, nil, "Bring the fifth and sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", "The 5th tablet is in Shadow Hunter Vosh'gajin's room, the 6th in War Master Voone's room. The reward comes from 'Facing Yeh'kinya'; Yeh'kinya is right beside Prospector Ironboot.", {{40,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {12740, 12741}, nil, 10460, "Prospector Ironboot", { xp = 7750 } },
        { 8181, nil, 40, 58, "Prospector Ironboot", "Tanaris - Steamwheedle Port 66.9,24", "The Final Tablets", false, {4788}, {20218, 20219}, "Go to Yeh'kinya in Tanaris and demand to know what happened to the Hakkar egg.", "Final step of the Hakkar chain: accept from Prospector Ironboot in Steamwheedle Port (66.9,24), turn in to Yeh'kinya next to him (67,22.4). Chain: Screecher Spirits → The Prophecy of Mosh'aru → ... → The Final Tablets → this quest; followed by 'Hand of Rastakhan'.", {{40,1}, {54,2}, {56,3}}, nil, nil, 10460, "Prospector Ironboot", { xp = 6200 } },
        { 5306, nil, 50, nil, "Kilram", "Winterspring - Everlook 61,37", nil, false, nil, { 12821 }, "Kill Shadow Hunter Vosh'gajin in Blackrock Spire and bring her ammonite to Kilram in Everlook, Winterspring.", "Lower Blackrock Spire (LBRS), not Upper. Vosh'gajin holds the room beside the hall guarded by three ogres: take the normal right-hand route, go down the ramp, then follow the fork toward the hall — her room is on the left of the fork. To skip trash use the shortcut: in the corridor before the first ogre pack there is a hole in the floor on the right; drop down to the ledge where Bijou stands, follow the path out to the down ramp and cross over, her room is on your left. Two Scarshield Shadow Priests stand with her — clear them first, then burn her; her hex can catch several players at once. A 5-player group is enough.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13352}, nil, 11192, "Kilram", { xp = 8300 } },
        { 4701, "A", 55, 59, "Helendis Riverhorn", "Burning Steppes - Morgan's Vigil 5,47", nil, false, nil, {15824, 15825, 15827}, "Destroy the source of the worgs in Blackrock Spire — \"Hareken\", the word Helendis shouted as a farewell, means \"worg\" in orcish.", "Hareken is inside the dungeon.", {{55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 9562, "Helendis Riverhorn", { xp = 6400, money = 18000, rep = { {69, 100, "Darnassus"} } } },
        { 4724, "H", 55, 59, "Galamav the Marksman", "Badlands - Kargath 5,47", nil, false, nil, {15824, 15825, 15827}, "Kill Hareken, the leader of the Bloodaxe worgs.", "Hareken is inside the dungeon.", {{55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 9081, "Galamav the Marksman", { xp = 6400, money = 18000, rep = { {76, 100, "Orgrimmar"} } } },
        { 4729, nil, 55, 59, "Kibler", "Burning Steppes - Flame Crest 65,22", nil, false, nil, {12264}, "Trap the Bloodaxe worg pups in Blackrock Spire: use the cage to subdue the little ones and bring the caged pup to Kibler.", "The worg pups are inside the dungeon.", {{55,2}, {57,3}, {62,4}, {71,5}}, {12263, 12262}, nil, 10260, "Kibler", { xp = 6400, money = 9000 } },
        { 4862, nil, 55, 59, "Kibler", "Burning Steppes - Flame Crest 65,22", nil, false, nil, {12529}, "Collect 15 Spirestone Spider Eggs for Kibler in Blackrock Spire.", "The spider eggs are inside the dungeon. Looting an egg can randomly spawn small spiders — they hit hard and have an AOE, watch out.", {{55,2}, {57,3}, {62,4}, {71,5}}, {12530}, nil, 10260, "Kibler", { xp = 6400, money = 9000 } },
        { 4866, nil, 55, 60, "Ragged John", "Burning Steppes - Flame Crest 65,23", nil, false, nil, {15873}, "Find the Queen of the Smokeweb at the heart of Blackrock Spire and fight her so she injects venom into you; kill her too if you can. Once poisoned, return to Ragged John and have him draw out the \"Queen's Milk\".", "The Queen of the Smokeweb is inside the dungeon. Note: cleansing the poison midway fails the quest.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9563, "Ragged John", { xp = 9950, money = 18000 } },
        { 4867, nil, 55, 60, "Warosh", "Lower Blackrock Spire", nil, true, nil, {15867}, "Read Warosh's scroll and return Warosh's cockroach to him.", "Flow: kill Omokk first for the head; the pike is inside the dungeon — use it to summon (several ogre packs spawn first; you can attack them with the pike). ◎ Only ONE person per spawn can turn this in — once turned in, he turns into his ogre form and no longer has the yellow '?'.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12712, 12730}, nil, 10799, "Warosh", { xp = 9950 } },
        { 4903, "H", 55, 60, "Warlord Goretooth", "Badlands - Kargath 65,22", nil, false, nil, {13958, 13959, 13961, 13962, 13963}, "Kill King Omokk, Commander Vohn and Vimsalak, find the important Blackrock documents, and report to Warlord Goretooth in Kargath.", "Locations: King Omokk, Commander Vohn, Vimsalak. The Blackrock documents are beside one of the bosses.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12562}, nil, 9077, "Warlord Goretooth", { xp = 8300, money = 18000, rep = { {76, 150, "Orgrimmar"} } } },
        { 4981, "H", 55, nil, "Lexlort", "Badlands - Kargath 5,47", nil, false, nil, nil, "Find out what happened to Bijou in Blackrock Spire.", "Bijou is inside the dungeon.", {{55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 9080, "Lexlort", { xp = 11850, rep = { { 21, 100, "Booty Bay" } } } },
        { 4982, "H", 55, 59, "Bijou", "Lower Blackrock Spire", "Bijou's Belongings", true, {4981}, nil, "Recover Bijou's device and return it to her — she remembers hiding it in the lowest level of the city.", "The device is on the way to the Queen of the Smokeweb.", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "Bijou", { xp = 6400 } },
        { 4983, "H", 55, 59, "Bijou", nil, nil, true, {4982}, {15858, 15859}, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12652}, nil, 10257, "Bijou", { xp = 6400, money = 18000, rep = { {76, 100, "Orgrimmar"} } } },
        { 5001, "A", 55, 59, "Bijou", "Lower Blackrock Spire", nil, true, nil, nil, "Recover Bijou's device and return it to her. Good luck!", "The device is on the way to Mother Smolderweb. Next, find Marshal Maxwell (Burning Steppes - Morgan's Vigil 84,58).", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "Bijou", { xp = 6400 } },
        { 5002, "A", 55, 59, "Bijou", nil, nil, true, {5001}, nil, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12770}, nil, 10257, "Bijou", { xp = 6400, money = 18000, rep = { {72, 100, "Stormwind City"} } } },
        { 5081, "A", 55, 60, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 84,58", "Maxwell's Mission", false, {5002}, {13958, 13959, 13961, 13962, 13963}, "Eliminate Commander Vohn, King Omokk and Vimsalak in Blackrock Spire, then report back to Marshal Maxwell.", "Locations: Vohn, King Omokk, Vimsalak.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "Marshal Maxwell", { xp = 8300, money = 18000, rep = { {72, 150, "Stormwind City"} } } },
        { 5089, "A", 55, 60, nil, "General Drakkisath's Command drops from (Vimsalak)", nil, true, nil, nil, "Bring General Drakkisath's Command to Marshal Maxwell in the Burning Steppes.", "Marshal Maxwell (Burning Steppes - Morgan's Vigil 84,58).", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12780}, nil, nil, nil, { xp = 6600, rep = { {72, 100, "Stormwind City"} } } },
        { 5103, nil, 56, nil, "Human Remains", "Lower Blackrock Spire", nil, false, nil, nil, "Someone in the world must know the origin of these gloves. Good luck!", "Blacksmithing quest. Get the plate gloves near the human remains and give them to Malyfous Darkhammer (Winterspring - Everlook 61,39).", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, nil, nil, { xp = 6600 } },
        { 4742, nil, 57, 60, "Akraed", "Lower Blackrock Spire", nil, true, nil, nil, "Find all three Gemstones of Command - Gemstone of Smolderthorn, Gemstone of Spirestone and Gemstone of Bloodaxe - and bring them with the Unadorned Seal of Ascension to Akride.", "Gem sources: King Omokk, Commander Vohn, Vimsalak. The Unforged Seal of Ascension drops from Blackrock Spire trash mobs. Completing this yields the key to Upper Blackrock Spire.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12336, 12335, 12337, 12219}, nil, 10299, "Akraed", { xp = 8300 } },
        { 4743, nil, 57, 60, "Akraed", nil, nil, true, {4742}, {12344}, nil, "Use the Unforged Seal in the water below the dragon to start the forging event. Each event yields only ONE lootable forged seal, and the dragon has a 3-hour cooldown — only one person can do it per night.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12324, 12339}, nil, 10299, "Akraed", { xp = 9950 } },
        { 8966, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "Vital Materials", false, {8962}, nil, "Use the summoning brazier to call out Mor Grayhoof's spirit and kill him; bring the brazier and the left half of the Vatalak Trinket back to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Mor Grayhoof is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22049}, nil, 16033, "Bodley", { xp = 8300 } },
    },
