        { 1193, nil, 56, nil, "A Broken Trap", "Dire Maul: North", nil, false, nil, nil, "Repair the trap.", "Repeatable. Repairing it requires a [Thorium Widget] and a vial of [Frost Oil].", {{56,2}, {58,3}, {63,4}, {72,5}}, {15994, 3829}, nil, nil, nil, nil },
        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "Doable in one run. Recommended route: North first (tribute run — bring the ogre-suit materials and the broken trap) → West (kill Immol'thar) → Library (kill Prince Tortheldrin) → back to North, turn in to Fengus on the way out.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 5518, nil, 56, 60, "Knot Thimblejack", "Dire Maul: North,", nil, true, nil, {18258}, "Bring 4 Runecloth, 8 Rugged Leather, 2 Rune Thread and an Ogre Tannin to Nott Shimjak, who is chained up in the Gordok ogre area of Dire Maul.", "Repeatable. The Ogre Tannin is obtained near the upper part of the instance.", {{56,2}, {58,3}, {63,4}, {72,5}}, {14048, 8170, 14341, 18240}, nil, 14338, "Knot Thimblejack", { xp = 6600, rep = { {169, 100, "Steamwheedle Port"} } } },
        { 7462, "A", 56, 60, "Shen'dralar Ancient", nil, "The Treasure of the Shen'dralar", true, {7461}, {18420, 18421, 18424}, nil, nil, {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, nil, { xp = 660, money = 27000 }},
        { 7703, nil, 56, nil, "Captain Kromcrush", "Dire Maul: North,", nil, false, nil, { 18366, 18367, 18368, 18369 }, "Find the Gauntlet of Gordok Might and bring it to Captain Kromcrush in Dire Maul.", "The prince is in Dire Maul West; the Gauntlets of Strength are in the chest near him. Recommended order: North first for the tribute, keeping the \"It's Good to Be King\" buff → West to kill the prince and open the chest → back North to turn in.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, 14325, "Captain Kromcrush", { xp = 22200 } },
        { 7877, "H", 56, 60, "Shen'dralar Ancient", "Dire Maul: West (upper level)", "The Treasure of the Shen'dralar", true, {7461}, {18420, 18421, 18424}, "Return to the Library to find the Shen'dralar treasure and claim your reward!", "The treasure is under the ladder in the Library.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "Shen'dralar Ancient", { xp = 660, money = 27000 } },
        { 5525, nil, 57, 60, "Knot Thimblejack", "Dire Maul: North,", nil, true, nil, nil, "Find the ogre shackle key for Nott.", "Repeatable; every ogre in the instance can drop it.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18250}, nil, 14338, "Knot Thimblejack", { xp = 6600, rep = { {169, 150, "Steamwheedle Port"} } } },
