        { 7506, nil, 54, 60, "The Emerald Dream", "May drop from any of the bosses across the Dire Maul dungeons", nil, false, nil, {18470}, "Turn this tome in to its owner.", "Druid class trinket quest. Bring it to Lorekeeper Yavo (Dire Maul: West - the Library).", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18364}, "Druid", nil, nil, { xp = 6600, money = 100, rep = { {809, 200, "Shen'dralar"} } } },
        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "Doable in one run. Recommended route: North first (tribute run — bring the ogre-suit materials and the broken trap) → West (kill Immol'thar) → Library (kill Prince Tortheldrin) → back to North, turn in to Fengus on the way out.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 7461, nil, 56, 60, "Shen'dralar Ancient", "Dire Maul: West (upper level)", nil, true, nil, nil, "Kill the guards around the five crystal pylons that keep Immol'thar imprisoned and drain the pylons until the force field collapses; enter the prison and kill the demon at its center; finally challenge Prince Tortheldrin in the library. When done, find the Shen'dralar Ancient in the courtyard.", "The crystal pylons, Immol'thar and Prince Tortheldrin are all inside the instance; the pylons must be shut down first.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "Shen'dralar Ancient", { xp = 9950 } },
        { 7462, "A", 56, 60, "Shen'dralar Ancient", nil, nil, true, {7461}, {18420, 18421, 18424}, nil, nil, {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, nil, { xp = 660, money = 27000 }},
        { 7877, "H", 56, 60, "Shen'dralar Ancient", "Dire Maul: West (upper level)", "The Treasure of the Shen'dralar", true, {7461}, {18420, 18421, 18424}, "Return to the Library to find the Shen'dralar treasure and claim your reward!", "The treasure is under the ladder in the Library.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "Shen'dralar Ancient", { xp = 660, money = 27000 } },
        { 5528, nil, 57, 60, "Trampler Craig", "Dire Maul: North,", nil, true, nil, {18269, 18284}, "Get free booze.", "Talk to Stomper Kreeg to accept and turn in at the same time; you must have the \"It's Good to Be King\" buff.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14322, "Trampler Craig", nil },
        { 8948, nil, 58, 60, "Anthion Harmon", "Eastern Plaguelands", "Anthion's Strange Request", false, {8947}, nil, nil, nil, {{58,3}, {63,4}, {72,5}}, {21983}, nil, 16016, "Anthion Harmon", { xp = 6600 } },
        { 8949, nil, 58, 60, "Falrin Treeshaper", nil, nil, true, {8948}, {22150, 22149}, nil, "Ogre Warbead drop rates: about 1/10 in Dire Maul North, 1/7 in LBRS (but far fewer ogres there), 1/50 outside the DM arena.", {{58,3}, {63,4}, {72,5}}, {21982}, nil, 16032, "Falrin Treeshaper", { xp = 6600 } },
        { 8950, nil, 58, 60, "Falrin Treeshaper", "Dire Maul", nil, true, {8949}, nil, nil, "The shadow essence drops from the ghosts in Dire Maul West.", {{58,3}, {63,4}, {72,5}}, {22224, 20520, 14344}, nil, 16032, "Falrin Treeshaper", { xp = 6600 } },
        { 8967, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "Vital Materials", false, {8963}, nil, "Use the summoning brazier to call out Isalien's spirit and kill her; return the brazier and the left half of the Vatalak Trinket to Bodley.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Isalien is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22050}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8990, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8985}, nil, "Use the summoning brazier to call out Isalien's spirit and kill it; return the brazier and Duke Vatalak's trinket to Bodley.", "You need the Extraplanar Ghost Revealer to see Bodley (from \"Finding Anthion\"). Isalien is summoned inside the instance.", {{58,3}, {63,4}, {72,5}}, {22048, 22050}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7507, nil, 60, 60, "Lorekeeper Lydros", "Dire Maul: West, the Library", nil, false, nil, nil, "Hand the Libram of Rapidity, 1 Primal Black Diamond, 2 Large Brilliant Shards and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul for a Quickening Elixir.", "No prerequisite, but the \"Elven Legends\" quest must be completed first. The libram drops randomly and is tradeable. Blood of Heroes spawns randomly on the ground in the Eastern and Western Plaguelands, picked up bound.", {{60,3}, {63,4}, {72,5}}, {18401}, nil, 14368, nil, { xp = 9950, rep = { {809, 200, "Shen'dralar"} } }},
        { 7508, nil, 60, 60, "Starts from the item [Dull and Flat Elven Blade]", nil, nil, true, {7507}, nil, nil, "'Foror's Compendium of Dragon Slaying' (drops in Dire Maul, tradeable) triggers the Quel'Serrar quest chain: hand the book to the lorekeeper in the Dire Maul West library to receive the 'Dull and Flat Elven Blade' and begin this epic weapon quest.", {{60,3}, {63,4}, {72,5}}, {18513}, nil, nil, nil, { xp = 9950 } },
        { 7631, nil, 60, nil, "Mor'zul", "Burning Steppes 12,31", "Dreadsteed of Xoroth", false, {7629}, { 23161 }, "Read Mor'zul's instructions, summon the Dreadsteed of Xoroth, defeat it and bind its soul.", "The final step of the warlock epic steed: shut down the crystal pylons and kill Immol'thar before you can summon. Bring at least 20 Soul Shards — maintaining the ritual circle consumes them continuously. After killing the steed, talk to its spirit to complete the quest.", {{60,3}, {4,4}, {6,5}}, {18818}, "Warlock", 14436, "Mor'zul Bloodbringer", { xp = 6600 } },
    },
    ["scholomance"] = {
        { 5341, "H", 52, 60, "Alexi Barov", "Tirisfal Glades - The Bulwark 80,73", nil, false, nil, nil, "Recover the four Barov family deeds from Scholomance (Caer Darrow, Brill, Tarren Mill and Southshore) and return them to Alexi Barov.", "Deed locations: Caer Darrow = in the first hall after entering; Southshore = on the desk in the left corner of the first large hall after crossing the bridge; Tarren Mill = on the desk in the right corner of the room before the whelps; Brill = in the room where Ras Frostwhisper is.", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11022, "Alexi Barov", { xp = 6600, money = 18000 } },
        { 5343, "A", 52, 60, "Weldon Barov", "Western Plaguelands - Chillwind Camp 43,83", nil, false, nil, nil, "Recover the four Barov family deeds from Scholomance (Caer Darrow, Brill, Tarren Mill and Southshore) and return them to Weldon Barov.", "Deed locations: Caer Darrow = in the first hall after entering; Southshore = on the desk in the left corner of the first large hall after crossing the bridge; Tarren Mill = on the desk in the right corner of the room before the whelps; Brill = in the room where Ras Frostwhisper is.", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11023, "Weldon Barov", { xp = 6600, money = 18000 } },
        { 5382, nil, 55, 60, "Eva Sarkhoff", "Western Plaguelands - Caer Darrow 70,73", nil, false, nil, nil, "Find Doctor Theolen Krastinov in Scholomance, kill him and burn the remains of Eva Sarkhoff and Lucien Sarkhoff, then report back to Eva Sarkhoff.", "After the doctor dies, look at the piles of flesh on both sides of the room — the remains of Eva and Lucien Sarkhoff are inside; clear them to complete.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11216, "Eva Sarkhoff", { xp = 6600 } },
        { 5384, nil, 55, 60, "Eva Sarkhoff", "Western Plaguelands - Caer Darrow 70,73", "Krastinov's Bag of Horrors", false, {5515}, {15805, 15806, 13544}, "Bring the Blood of Innocents back to Scholomance and pour it into the brazier on the porch to draw out Kirtonos the Herald; face him bravely and do not flinch. Kill him and report back to Eva Sarkhoff.", "The vestibule is inside the dungeon. The Blood of Innocents drops 100% from the succubus in the first room; if the summoned Kirtonos doesn't drop the reward you want, abandon and re-take the quest (the instance must be reset to summon again).", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13523}, nil, 11216, "Eva Sarkhoff", { xp = 8300 } },
        { 5515, nil, 55, 60, "Eva Sarkhoff", "Western Plaguelands - Caer Darrow 70,73", "Doctor Theolen Krastinov", false, {5382}, nil, "Defeat Jandice Barov in Scholomance, take Krastinov's Bag of Horrors from her corpse and bring it to Eva Sarkhoff.", "Jandice Barov is inside the dungeon. Only the real body has a health bar among the clones — turn on nameplates (V) or mark the real one, and only hit the one with the bar.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13725}, nil, 11216, "Eva Sarkhoff", { xp = 6600 } },
        { 5529, nil, 55, 58, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", nil, false, nil, nil, "Kill 20 Plague Dragon Whelps and report back to Betina Bigglezink at Light's Hope Chapel.", "The Plague Dragon Whelps are in the bone vault — the big chamber on the way to the Bloodbone Golem.", {{55,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 11035, "Betina Bigglezink", { xp = 6200, money = 9000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5582, nil, 55, nil, "Healthy Dragon Scale", "Random drop from Plaguebats in Scholomance", "Healthy Dragon Scale", false, {5529}, nil, "Bring the Healthy Dragon Scale to Betina Bigglezink at Light's Hope Chapel in Eastern Plaguelands.", "You must complete 'Plagued Hatchlings' first before the lootable Healthy Dragon Scale appears (otherwise you can't see it). Healthy Dragon Scales drop from Plagued Hatchlings (about 8%). Betina Bigglezink (Eastern Plaguelands - Light's Hope Chapel 76,54).", {{55,2}, {56,3}, {61,4}, {69,5}}, {13920}, nil, nil, nil, { rep = { { 529, 50, "Argent Dawn" } } } },
        { 4771, nil, 57, 60, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 77,54", "Betina Bigglezink", false, {5531}, {15853, 15854}, "Place the Dawn's Gambit in the Viewing Room of Scholomance, defeat Vectus, then report back to Betina Bigglezink.", "The prerequisite \"Dragonkin Essence\" starts with Tinkee Steamboil (Burning Steppes - Flame Crest 65,23). The observation room is inside the dungeon.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12368}, nil, 11035, "Betina Bigglezink", { xp = 9950, money = 27000, rep = { {529, 200, "Argent Dawn"} } } },
        { 5466, nil, 57, 60, "Magistrate Marduke", "Western Plaguelands - Caer Darrow 70,73", "The Lich, Ras Frostwhisper", false, {5465}, {13982, 13986, 13984, 14002}, "Find Ras Frostwhisper in Scholomance and use the Soulbound Keepsake to break his undead shell; once it works, kill him and bring his head to Magistrate Marduke.", "Ras Frostwhisper is inside the instance.", {{57,2}, {58,3}, {63,4}, {72,5}}, {13626, 13752}, nil, 11286, "Magistrate Marduke", { xp = 9950 } },
        { 5531, nil, 57, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands 81.6,57.8", "Leonid Barthalomew the Revered", false, {5522}, nil, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {13761}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 1650, rep = { {529, 25, "Argent Dawn"} } }},
        { 8258, "H", 58, nil, "Sagorne Creststrider", "Orgrimmar - Valley of Wisdom 38.6, 36.2", "The Darkreaver Menace", false, {7667}, { 20134 }, "Use the Divination Scryer at the center of the bone vault in Scholomance's basement and defeat the summoned ghosts; when Death Knight Darkreaver appears, defeat him too and take his head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", "Shaman-only quest; the prerequisite is taken from the same NPC. Darkreaver is summoned inside the instance.", {{58,3}, {63,4}, {72,5}}, {18880, 18746}, "Shaman", 13417, nil, { xp = 9950, rep = { { 67, 200, "[UNUSED] Brother Milius" } } }},
        { 8969, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "Vital Materials", false, {8965}, nil, "Use the summoning brazier to call out Kormok's spirit and kill him; return the brazier and the left half of the Vatalak Trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Kormok is inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22052}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8992, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8988}, nil, "Use the summoning brazier to call out Kormok's spirit and kill him; return the brazier and Duke Vatalak's trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Kormok is inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22052}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7629, nil, 60, nil, "Gorzeeki Wildeyes", "Burning Steppes 12,31", "Imp Delivery", false, {7625}, nil, "Take the imp in the bottle to the alchemy lab in Scholomance; once it produces the parchment, return the bottle to Gorzeeki Wildeyes.", "Warlock only! The alchemy lab is in the same room as Ras Frostwhisper.", {{60,3}, {4,4}, {6,5}}, {18688}, "Warlock", 14437, "Gorzeeki Wildeyes", { xp = 6600 } },
        { 7647, "A", nil, nil, nil, nil, nil, false, {7646}, nil, nil, nil, {{60,3}, {4,4}, {6,5}}, {18799, 18792, 18804}, "Paladin", 928, "Lord Grayson Shadowbreaker", { xp = 9950, rep = { { 72, 200, "Stormwind City" } } } },
    },
    ["stratholme_main"] = {
        { 5305, nil, 50, nil, "Lilith the Lithe", "Winterspring - Everlook 61,37", nil, false, nil, { 12824 }, "Kill the Crimson Hammerer in Stratholme and bring his apron to Lilith the Lithe.", "The Crimson Hammersmith is a triggered spawn: click the 'Blacksmithing Plans' parchment on the ground to trigger it.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "Lilith the Lithe", nil },
        { 5307, nil, 50, nil, "Seril Scourgebane", "Winterspring - Everlook 61,37", nil, false, nil, { 12825 }, "Find and kill the Black Guard Swordsmith in Stratholme and bring the Black Guard Medallion to Seril Scourgebane.", "The Dark Iron Guardsmith is a triggered spawn: click the 'Blacksmithing Plans' parchment on the ground next to the pawn shop beside Anastari's ziggurat.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "Seril Scourgebane", nil },
        { 5848, nil, 52, 60, "Artist Renfray", "Western Plaguelands - Caer Darrow 65,75", "Of Love and Family", false, {5846}, nil, "Go to the Scarlet Crusade bastion in Stratholme and recover the painting \"Of Love and Family\" (hidden behind another painting of the twin moons), and return it to Tirion Fordring.", "The prerequisite comes from Tirion Fordring (Western Plaguelands 7,43). The painting is on your right as you enter the archives in the Living side.", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "Artist Renfray", { xp = 6600 } },
        { 5125, nil, 55, 60, "Aurius", "Stratholme", "Aurius' Reckoning", true, {5122}, {17044, 17045}, "Kill Baron Rivendare.", "First give Aurius [Aurius' Reckoning] (the medallion is inside Malor's Strongbox in the instance); he will join the fight against the Baron but will fall. After killing the Baron, talk to his corpse to complete the quest.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "Aurius", { xp = 9950 } },
        { 5212, nil, 55, nil, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", nil, false, nil, nil, "Recover 20 Plagued Flesh Samples from Stratholme and bring them to Betina Bigglezink.", "Most enemies in Stratholme drop the flesh samples, but the drop rate is low.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "Betina Bigglezink", { xp = 6600, money = 18000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5213, nil, 55, 60, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", "The Active Agent", false, {5212}, {13209, 19812}, "Search the ziggurats of Stratholme for the new Scourge archive and bring it to Betina Bigglezink.", "The small box spawns randomly in ONE of the three ziggurats (Nerub'enkan, Baroness Anastari, Maleki); it does not disappear — every party member can loot it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "Betina Bigglezink", { xp = 6600, rep = { {529, 100, "Argent Dawn"} } } },
        { 5214, nil, 55, 60, "Smokey LaRue", "Eastern Plaguelands - Light's Hope Chapel 75,52", nil, false, nil, {13171}, "Find Fras Siabi's tobacco shop in Stratholme, retrieve a box of Siabi's Tobacco and bring it to Smokey LaRue.", "The tobacco shop is inside the dungeon: keep turning left to the dead end, to the right of the well — clear everything along the way. Fras Siabi appears the moment you open the box.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "Smokey LaRue", { xp = 8300 } },
        { 5243, nil, 55, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "Head to Stratholme, loot the supply crates scattered around the city, collect 5 Stratholme Holy Water and report back to Leonid Barthalomew the Revered.", "The holy water is in crates all over the city; some are fakes that burst into a swarm of bugs. Dwarves can use 'Find Treasure' to mark the real crates on the minimap.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600, money = 18000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5251, nil, 55, 60, "Duke Nicholas Zverenhoff", "Eastern Plaguelands - Light's Hope Chapel 76,52", nil, false, nil, nil, "Find the Scarlet crusade's Archivist Galford in Stratholme, kill him and burn the Scarlet Crusade archives.", "The archives and the Archivist are both inside the dungeon. ◎ If you are also doing 'Of Love And Family': grab the painting BEFORE burning the archives — the painting burns together with them.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "Duke Nicholas Zverenhoff", { xp = 8300, money = 18000, rep = { {529, 150, "Argent Dawn"} } } },
        { 5262, nil, 55, 60, "Balnazzar", "Stratholme", "The Truth Comes Crashing Down", false, {5251}, nil, "Bring Balnazzar's head to Duke Nicholas Zverenhoff in Eastern Plaguelands.", "The Duke is at (Eastern Plaguelands - Light's Hope Chapel 76,52).", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, 10813, "Balnazzar", { xp = 8300, rep = { {529, 150, "Argent Dawn"} } } },
        { 5263, nil, 55, nil, "Duke Nicholas Zverenhoff", "Eastern Plaguelands - Light's Hope Chapel 76,52", "Above and Beyond", false, {5262}, nil, "Kill Baron Rivendare in Stratholme and bring his head to Duke Nicholas Zverenhoff.", "The Baron is inside the instance. This quest has a follow-up that grants the reward.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "Duke Nicholas Zverenhoff", { xp = 8300, rep = { {529, 150, "Argent Dawn"} } } },
        { 5282, nil, 55, 60, "Egan", "Eastern Plaguelands 11,29", "The Restless Souls", false, {5281}, {13315}, "Use Egan's Blaster on the ghostly residents of Stratholme; use it once more after their souls leave the bodies to put them to rest for good. Free 15 Restless Souls and report back to Egan.", "Pick up the prerequisite from Caretaker Alen (Eastern Plaguelands - Light's Hope Chapel 74,58). Spectral citizens wander all over the city. About 10 seconds after you hit a ghost with the blaster, a 'Restless Soul' appears beside it; shoot it once more and you can loot it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "Egan", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, nil, "Nathanos Blightcaller", "Eastern Plaguelands 22,68", "Ramstein", false, {6135}, nil, "Kill Ramstein the Gorger in Stratholme and bring his head to Nathanos.", "The prerequisite is likewise taken from Nathanos. Ramstein is inside the instance.", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "Nathanos Blightcaller", { xp = 6600, money = 18000, rep = { {68, 100, "Undercity"} } } },
        { 5463, nil, 57, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 75,52", "Menethil's Gift", false, {5462}, nil, "Find Menethil's Gift in Stratholme and place the lich's mortal remains on that evil ground.", "The prerequisite is from Magistrate Marduke (Western Plaguelands - Caer Darrow 70,73). The marker is the pentagram on the floor of the Baron's room. See also Scholomance's \"Lich Ras Frostwhisper\".", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600 } },
        { 8945, nil, 58, 60, "Ysida Harmon", "Eastern Plaguelands - Stratholme", "Dead Man's Plea", false, {8929}, {22137}, "Enter Stratholme and rescue Ysida Harmon from Baron Rivendare.", "Ysida Harmon stands right at the dungeon entrance; you need the Extra-Dimensional Ghost Revealer to see her. Prerequisite: Alliance see Deliana (Ironforge 43,52), Horde see Mokvar (Orgrimmar 38,37). This is also the famous '45-minute Rivendare' quest.", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "Anthion Harmon", { xp = 8300 } },
        { 8968, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "Vital Materials", false, {8964}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and the left half of the Vatalak Trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8991, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "More Vital Materials", false, {8987}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and Duke Vatalak's trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7622, nil, 60, nil, "Eris Havenfire", "Eastern Plaguelands 17,14", "The Balance of Light and Shadow", false, {7621}, nil, "Save 50 farmers before 15 of them are killed, then talk to Eris Havenfire when done. The death notices show your rescue progress.", "You need the Eye of Divinity (from the chest of the Firelord in Molten Core) to meet Eris Havenfire and take the quest. On completion, combine the Eye of Divinity, the Splinter of Nordrassil and the Eye of Shadow (random demon drops in Blasted Lands / Winterspring) to obtain the priest epic staff — Benediction.", {{60,3}, {63,4}, {72,5}}, nil, "Priest", 14494, "Eris Havenfire", nil },
        { 9257, nil, 60, nil, "Anachronos", "Tanaris - Caverns of Time 65,49", "Atiesh, Greatstaff of the Guardian", false, {9251}, nil, "Anachronos of the Caverns of Time in Tanaris wants you to travel to Stratholme, use Atiesh, Greatstaff of the Guardian on the hallowed ground, defeat the creatures driven out, then report back to him.", "The summoning spot is inside the instance. In the Wrath of the Lich King expansion this quest can no longer be obtained; only the \"summon Atiesh\" step remains completable.", {{60,3}, {63,4}, {72,5}}, {22737}, "Priest", 15192, nil, nil},
    },
    ["stratholme_service"] = {
        { 5305, nil, 50, nil, "Lilith the Lithe", "Winterspring - Everlook 61,37", nil, false, nil, { 12824 }, "Kill the Crimson Hammerer in Stratholme and bring his apron to Lilith the Lithe.", "The Crimson Hammersmith is a triggered spawn: click the 'Blacksmithing Plans' parchment on the ground to trigger it.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "Lilith the Lithe", { xp = 8300 } },
        { 5307, nil, 50, nil, "Seril Scourgebane", "Winterspring - Everlook 61,37", nil, false, nil, { 12825 }, "Find and kill the Black Guard Swordsmith in Stratholme and bring the Black Guard Medallion to Seril Scourgebane.", "The Dark Iron Guardsmith is a triggered spawn: click the 'Blacksmithing Plans' parchment on the ground next to the pawn shop beside Anastari's ziggurat.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "Seril Scourgebane", { xp = 8300 } },
        { 5848, nil, 52, 60, "Artist Renfray", "Western Plaguelands - Caer Darrow 65,75", "Of Love and Family", false, {5846}, nil, "Go to the Scarlet Crusade bastion in Stratholme and recover the painting \"Of Love and Family\" (hidden behind another painting of the twin moons), and return it to Tirion Fordring.", "The prerequisite comes from Tirion Fordring (Western Plaguelands 7,43). The painting is on your right as you enter the archives in the Living side.", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "Artist Renfray", { xp = 6600 } },
        { 5125, nil, 55, 60, "Aurius", "Stratholme", "Aurius' Reckoning", true, {5122}, {17044, 17045}, "Kill Baron Rivendare.", "First give Aurius [Aurius' Reckoning] (the medallion is inside Malor's Strongbox in the instance); he will join the fight against the Baron but will fall. After killing the Baron, talk to his corpse to complete the quest.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "Aurius", { xp = 9950 } },
        { 5212, nil, 55, 60, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", nil, false, nil, nil, "Recover 20 Plagued Flesh Samples from Stratholme and bring them to Betina Bigglezink.", "Most enemies in Stratholme drop the flesh samples, but the drop rate is low.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "Betina Bigglezink", { xp = 6600, money = 18000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5213, nil, 55, 60, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", "The Active Agent", false, {5212}, {13209, 19812}, "Search the ziggurats of Stratholme for the new Scourge archive and bring it to Betina Bigglezink.", "The small box spawns randomly in ONE of the three ziggurats (Nerub'enkan, Baroness Anastari, Maleki); it does not disappear — every party member can loot it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "Betina Bigglezink", { xp = 6600, rep = { {529, 100, "Argent Dawn"} } } },
        { 5214, nil, 55, 60, "Smokey LaRue", "Eastern Plaguelands - Light's Hope Chapel 75,52", nil, false, nil, {13171}, "Find Fras Siabi's tobacco shop in Stratholme, retrieve a box of Siabi's Tobacco and bring it to Smokey LaRue.", "The tobacco shop is inside the dungeon: keep turning left to the dead end, to the right of the well — clear everything along the way. Fras Siabi appears the moment you open the box.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "Smokey LaRue", { xp = 8300 } },
        { 5243, nil, 55, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "Head to Stratholme, loot the supply crates scattered around the city, collect 5 Stratholme Holy Water and report back to Leonid Barthalomew the Revered.", "The holy water is in crates all over the city; some are fakes that burst into a swarm of bugs. Dwarves can use 'Find Treasure' to mark the real crates on the minimap.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600, money = 18000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5251, nil, 55, nil, "Duke Nicholas Zverenhoff", "Eastern Plaguelands - Light's Hope Chapel 76,52", nil, false, nil, nil, "Find the Scarlet crusade's Archivist Galford in Stratholme, kill him and burn the Scarlet Crusade archives.", "The archives and the Archivist are both inside the dungeon. ◎ If you are also doing 'Of Love And Family': grab the painting BEFORE burning the archives — the painting burns together with them.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "Duke Nicholas Zverenhoff", { xp = 8300, money = 18000, rep = { {529, 150, "Argent Dawn"} } } },
        { 5262, nil, 55, nil, "Balnazzar", "Stratholme", "The Truth Comes Crashing Down", false, {5251}, nil, "Bring Balnazzar's head to Duke Nicholas Zverenhoff in Eastern Plaguelands.", "The Duke is at (Eastern Plaguelands - Light's Hope Chapel 76,52).", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, 10813, "Balnazzar", { xp = 8300, rep = { {529, 150, "Argent Dawn"} } } },
        { 5263, nil, 55, 60, "Duke Nicholas Zverenhoff", "Eastern Plaguelands - Light's Hope Chapel 76,52", "Above and Beyond", false, {5262}, nil, "Kill Baron Rivendare in Stratholme and bring his head to Duke Nicholas Zverenhoff.", "The Baron is inside the instance. This quest has a follow-up that grants the reward.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "Duke Nicholas Zverenhoff", { xp = 8300, rep = { {529, 150, "Argent Dawn"} } } },
        { 5282, nil, 55, 60, "Egan", "Eastern Plaguelands 11,29", "The Restless Souls", false, {5281}, {13315}, "Use Egan's Blaster on the ghostly residents of Stratholme; use it once more after their souls leave the bodies to put them to rest for good. Free 15 Restless Souls and report back to Egan.", "Pick up the prerequisite from Caretaker Alen (Eastern Plaguelands - Light's Hope Chapel 74,58). Spectral citizens wander all over the city. About 10 seconds after you hit a ghost with the blaster, a 'Restless Soul' appears beside it; shoot it once more and you can loot it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "Egan", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, 60, "Nathanos Blightcaller", "Eastern Plaguelands 22,68", "Ramstein", false, {6135}, {18022, 17001}, "Kill Ramstein the Gorger in Stratholme and bring his head to Nathanos.", "The prerequisite is likewise taken from Nathanos. Ramstein is inside the instance.", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "Nathanos Blightcaller", { xp = 6600, money = 18000, rep = { {68, 100, "Undercity"} } } },
        { 5463, nil, 57, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 75,52", "Menethil's Gift", false, {5462}, nil, "Find Menethil's Gift in Stratholme and place the lich's mortal remains on that evil ground.", "The prerequisite is from Magistrate Marduke (Western Plaguelands - Caer Darrow 70,73). The marker is the pentagram on the floor of the Baron's room. See also Scholomance's \"Lich Ras Frostwhisper\".", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600 } },
        { 8945, nil, 58, 60, "Ysida Harmon", "Eastern Plaguelands - Stratholme", "Dead Man's Plea", false, {8929}, {22137}, "Enter Stratholme and rescue Ysida Harmon from Baron Rivendare.", "Ysida Harmon stands right at the dungeon entrance; you need the Extra-Dimensional Ghost Revealer to see her. Prerequisite: Alliance see Deliana (Ironforge 43,52), Horde see Mokvar (Orgrimmar 38,37). This is also the famous '45-minute Rivendare' quest.", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "Anthion Harmon", { xp = 8300 } },
        { 8968, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "Vital Materials", false, {8964}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and the left half of the Vatalak Trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8991, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "More Vital Materials", false, {8987}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and Duke Vatalak's trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7622, nil, 60, nil, "Eris Havenfire", "Eastern Plaguelands 17,14", "The Balance of Light and Shadow", false, {7621}, { 18659 }, "Save 50 farmers before 15 of them are killed, then talk to Eris Havenfire when done. The death notices show your rescue progress.", "You need the Eye of Divinity (from the chest of the Firelord in Molten Core) to meet Eris Havenfire and take the quest. On completion, combine the Eye of Divinity, the Splinter of Nordrassil and the Eye of Shadow (random demon drops in Blasted Lands / Winterspring) to obtain the priest epic staff — Benediction.", {{60,3}, {63,4}, {72,5}}, nil, "Priest", 14494, "Eris Havenfire", { xp = 9950 } },
        { 9257, nil, 60, nil, "Anachronos", "Tanaris - Caverns of Time 65,49", "Atiesh, Greatstaff of the Guardian", false, {9251}, { 22631 }, "Anachronos of the Caverns of Time in Tanaris wants you to travel to Stratholme, use Atiesh, Greatstaff of the Guardian on the hallowed ground, defeat the creatures driven out, then report back to him.", "The summoning spot is inside the instance. In the Wrath of the Lich King expansion this quest can no longer be obtained; only the \"summon Atiesh\" step remains completable.", {{60,3}, {63,4}, {72,5}}, {22737}, "Priest", 15192, nil, { xp = 9950, rep = { { 910, 200, "Brood of Nozdormu" }, { 529, 200, "Argent Dawn" } } }},
    },
    ["upper_blackrock_spire"] = {
        { 6502, "A", 50, 60, "Haleh", "Winterspring 54.4,51.2", "Drakefire Amulet", false, {6501}, {16309}, nil, nil, {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10929, "Haleh", { xp = 8300 }},
        { 4974, "H", 55, 60, "Thrall", "Orgrimmar 31,38", "For The Horde!", false, {4941}, {13966, 13968, 13965}, "Kill Warchief Rend Blackhand in Blackrock Spire and return to Orgrimmar with his head.", "Rend Blackhand is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12630}, nil, 4949, "Thrall", { xp = 9950, money = 27000, rep = { {76, 200, "Orgrimmar"}, {530, 200, "Darkspear Trolls"}, {68, 200, "Undercity"}, {81, 200, "Thunder Bluff"} } } },
        { 5047, nil, 55, 60, "Finkle Einhorn", "Upper Blackrock Spire", nil, true, nil, nil, "Talk with Marevus Darkhammer in Everlook.", "Finkle Einhorn only appears after you skin The Beast. Marevus Darkhammer (Winterspring - Everlook 61,38).", {{57,2}, {58,3}, {63,4}, {72,5}}, {12710}, nil, 10776, "Pip Quickwit", { xp = 6600 } },
        { 5102, "A", 55, 60, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 82,68", "General Drakkisath's Demise", false, {5089}, {13966, 13968, 13965}, "Kill General Drakkisath in Blackrock Spire and report back to Marshal Maxwell.", "General Drakkisath is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "Marshal Maxwell", { xp = 9950, money = 27000, rep = { {469, 200, "[UNUSED] Brother Milius"} } } },
        { 5127, nil, 55, 60, "Lorax", "Winterspring 64,74", "The Demon Forge", false, {5126}, {12696, 9224, 12849}, "Find Gularuk in Blackrock Spire; after killing him, thrust the Bloodstained Spear into the corpse to drain its soul and forge the Soulpiercer; then find an unforged Runed Breastplate and bring both to Lorax in Winterspring.", "Blacksmithing quest. Goraluk is inside the dungeon. Requires Blacksmithing 270 to pick up.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12847, 12806, 12848}, nil, 10918, "Lorax", { xp = 8300 } },
        { 6569, "H", 55, nil, "Myranda the Hag", "Western Plaguelands 50,77", "Oculus Illusions", false, {6568}, nil, "Collect 20 Black Dragon Whelp eyes in Blackrock Spire, then report back to Myranda the Hag.", "All black dragonkin drop the eyes.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16786}, nil, 11872, "Myranda the Hag", { xp = 6600 } },
        { 6602, "H", 55, 60, "Rokaro", "Desolace - Shadowprey Village 25,71", "Blood of the Black Dragon Champion", false, {6601}, {16309}, "Kill General Drakkisath in Blackrock Spire and bring his blood to Rokaro.", "The final step of the Onyxia prerequisite chain. General Drakkisath is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10182, "Rokaro", { xp = 9950 } },
        { 6821, nil, 55, nil, "Duke Hydraxis", "Azshara 79,73", "Eye of the Emberseer", false, {6804}, nil, "Bring the Eye of Ebohir to Duke Hydraxis in Azshara.", "Ebohir is inside the instance. This quest chain can no longer be started after patch 3.0.8; characters who already have it are unaffected and can still complete it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {17322}, nil, 13278, "Duke Hydraxis", { xp = 8300 } },
        { 7761, nil, 55, nil, nil, "Blackhand's Command drops from the Scarshield Quartermaster (on the dungeon entrance map).", nil, true, nil, nil, "What a dim-witted orc — find the brand and obtain Drakkisath's Badge before you can use the Orb of Command.", "The Blackwing Lair attunement quest. The Scarshield Quartermaster is near the right side of the Blackrock Spire entrance; the orb is behind General Drakkisath.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18987}, nil, nil, nil, { xp = 6600 } },
        { 4734, nil, 57, 60, "Tinkee Steamboil", "Burning Steppes - Flame Crest 65,24", "Tinkee Steamboil", false, {4810}, {12144}, "Use the Egg Freezer Mark I on a dragon egg in the hatchery.", "The eggs are in the Father Flame's room. After freezing an egg do NOT click it — use the device from your backpack; after killing General Drakkisath you can jump straight down to the rookery and finish it separately.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12286}, nil, 10267, "Tinkee Steamboil", { xp = 8300, money = 18000, rep = { {169, 150, "Steamwheedle Port"} } } },
        { 4735, nil, 57, 60, "Tinkee Steamboil", "Burning Steppes - Flame Crest 65,24", "Egg Collection", false, {4734}, nil, "Bring the Electric Collection Module and 8 dragon eggs to Tinkee Steamboil at Flame Crest in the Burning Steppes.", "The eggs are all in the Father Flame's room. After freezing an egg, get close and use the device from your backpack (don't click the egg); if the raid won't wait, jump down to the rookery after the General to finish it solo.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12241, 12287}, nil, 10267, "Tinkee Steamboil", { xp = 9950, money = 27000, rep = { {169, 200, "Steamwheedle Port"} } } },
        { 4764, "A", 57, 60, "Mayara Brightwing", "Burning Steppes - Morgan's Vigil 84,69", "Mayara Brightwing", false, {4766}, nil, "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", "The prerequisite can be picked up from Count Remington Ridgewell (Stormwind - Stormwind Keep 77,47). The buckle is in the chest in Father Flame's room. The chest respawns roughly every 20 seconds, so several players can take turns opening it.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12352}, nil, 9565, "Mayara Brightwing", { xp = 1650, rep = { {72, 25, "Stormwind City"} } } },
        { 4765, "A", 57, 60, "Mayara Brightwing", "Burning Steppes 84.8,69.0", nil, false, {4764}, {15861, 15860}, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {12437}, nil, 9565, "Mayara Brightwing", { xp = 6600, money = 27000, rep = { {72, 100, "Stormwind City"} } }},
        { 4768, "H", 57, 60, "Vivian Lagrave", "Badlands - Kargath 2,47", "The Darkstone Tablet", false, {4769}, {15861, 15860}, "Bring the Darkstone Tablet to Shadowmage Vivian Lagrave in Kargath.", "The prerequisite is from Apothecary Zinge (Undercity - Apothecarium 50,68). The slab is in the dragon egg room (Hatchery) in Upper Blackrock Spire.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12358}, nil, 9078, "Shadowmage Vivian Lagrave", { xp = 8300, money = 27000, rep = { {68, 150, "Undercity"} } } },
        { 5160, nil, 57, 60, "Awbee", "Upper Blackrock Spire", nil, true, nil, nil, "Find Haleh in Winterspring and bring her Awbee's scale.", "Awbee is in the room next to the arena, crouched on a ledge. Haleh (Winterspring 54,51): step onto the teleport rune at the very back of the cave to reach her.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12923}, nil, 10740, "Awbee", { xp = 6600 } },
        { 8989, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8986}, nil, "Use the summoning brazier in the Beast's room to call out Duke Vatalak; after killing him, use the Vatalak Trinket on the corpse, then return the trinket to the Spirit of Duke Vatalak.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Mor Grayhoof is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22049}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8994, nil, 58, nil, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "The Right Half of the Vatalak Trinket", false, {8989}, nil, "Collect 40 Blackrock bracers from the orcs of Blackrock Spire and hand them, together with 1 Super Energy Potion, to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The bracers drop from Blackrock Spire orcs; the Super Energy Potion is an alchemy product.", {{58,3}, {63,4}, {72,5}}, {22138, 13512, 22048}, nil, 16033, "Bodley", { xp = 6600 } },
        { 8995, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "The Final Preparation", false, {8994}, nil, "Use the summoning brazier in the Beast's room to call out Duke Vatalak; after killing him, use the Vatalak Trinket on the corpse, then return the trinket to the Spirit of Duke Vatalak.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Duke Vatalak is summoned inside the dungeon; claim the reward from Bodley.", {{58,3}, {63,4}, {72,5}}, {22048, 22056}, nil, 16033, "Bodley", { xp = 9950 } },
    },
    ["onyxias_lair"] = {
        { 4182, "A", 48, 54, "Helendis Riverhorn", "Burning Steppes - Morgan's Vigil 85.6,69", nil, false, nil, nil, "Slay the black dragonkin in Burning Steepes and report back to Helendis Riverhorn.", "Alliance attunement step one. Black Broodlings and whelps are non-elite; Black Dragonspawn, Wyrmkin and Drakes are level 50-54 elites — bring a group. They are all strung along the eastern edge of the zone.", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9562, "Helendis Riverhorn", { xp = 5450, rep = { { 69, 100, "Darnassus" } } } },
        { 4183, "A", 48, 54, "Helendis Riverhorn", "Burning Steppes - Morgan's Vigil 85.6,69", nil, false, {4182}, nil, "Deliver Helendis Riverhorn's letter to Magistrate Solomon in Lakeshire, Redridge Mountains.", "The same-named quest has five parts, moving from Lakeshire all the way to Stormwind City. This part ends at: Lakeshire Town Hall (Redridge Mountains 30,44).", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 344, "Magistrate Solomon", { xp = 4100, rep = { { 69, 75, "Darnassus" } } } },
        { 4241, "A", 50, 58, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 84.6,68.8", nil, false, {4183}, nil, "Visit Marshal Windsor in the Blackrock Depths jail and deliver Marshal Maxwell's letter to him.", "Windsor is in the cell at the end of the corridor on the right side of the BRD jail block. Do not mix the two up: Marshal Maxwell is at Morgan's Vigil in Burning Steepes, while Marshal Windsor is in the BRD jail.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9023, "Marshal Windsor", { xp = 11450, rep = { { 72, 100, "Stormwind City" } } } },
        { 6402, "A", 50, 60, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 84.6,68.8", nil, false, {4322}, nil, "Find Squire Rowe at the gates of Stormwind City to summon Reginald Windsor, then escort him from the gates to Stormwind Keep.", "The escort takes about 10 minutes. If another party is already escorting him, Windsor says he is indisposed at the moment — wait a few minutes and he will show up.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 12580, "Reginald Windsor", { xp = 660 } },
        { 6403, "A", 50, 60, "Reginald Windsor", "Stormwind City - main gates 70.4,85.6", nil, false, {6402}, nil, "March with Reginald Windsor to Stormwind Keep, defeat the elite dragonkin guards summoned when Lady Katrana Prestor reveals her true form, then report to Highlord Bolvar Fordragon.", "The Great Masquerade: Lady Prestor reveals herself as Onyxia and summons elite dragonkin guards; the nearby guard NPCs help tank them. Turn in the quest once everything is defeated.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 1748, "Highlord Bolvar Fordragon", { xp = 9950, rep = { { 72, 200, "Stormwind City" } } } },
        { 6501, "A", 50, 60, "Highlord Bolvar Fordragon", "Stormwind City", nil, false, {6403}, nil, "Take the Fragment of the Dragon's Eye deep into the cave of Mazthoril in southern Winterspring to find Haleh, a dragon disguised as a humanoid.", "Haleh stands at the teleport runes at the end of the cave — step on the runes to reach her. The cave is stuffed with elite dragons: clear through with a group, stealth down, or sprint straight to her.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 10929, "Haleh", { xp = 6600 } },
        { 4941, "H", 55, 60, "Warlord Goretooth", "Badlands - Kargath 5.8,47.6", nil, false, {4903}, nil, "Speak with Eitrigg in the Valley of Wisdom in Orgrimmar, then bring his words to Thrall.", "Eitrigg is in the Valley of Wisdom (34.4,38.4); after talking, go straight back to Thrall (Orgrimmar 31,38) to turn in.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "Thrall", { xp = 6600, rep = { { 76, 100, "Orgrimmar" } } } },
        { 6566, "H", 55, 60, "Thrall", "Orgrimmar 31,38", nil, false, {4974}, nil, "Listen to Thrall's tale, then turn the quest in to him.", "A pure dialogue quest — just stand there and listen.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "Thrall", { xp = 660 } },
        { 6567, "H", 55, 60, "Thrall", "Orgrimmar 31,38", nil, false, {6566}, nil, "Find Rexxar, champion of the Horde, in Desolace.", "Rexxar patrols back and forth along the road between Stonetalon Mountains and Feralas, cutting through the Kodo Graveyard midway. If you cannot find him, ask in Desolace general chat, or run north from Feralas — that is the easiest way to catch him.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "Rokaro", { xp = 3300 } },
        { 6568, "H", 55, 60, "Rokaro", "Desolace - road toward Feralas", nil, false, {6567}, nil, "Deliver Rexxar's testament to Myranda the Hag near Uther's Tomb in Western Plaguelands.", "Myranda the Hag (Western Plaguelands 50,77) teaches you how to disguise yourself as a member of the Black Dragonflight.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11872, "Myranda the Hag", { xp = 4950 } },
        { 6570, "H", 55, 60, "Myranda the Hag", "Western Plaguelands 50,77", nil, false, {6569}, nil, "Wear the Amulet of Draconic Subversion and speak with Emberstrife inside the cave at the southernmost tip of Dustwallow Marsh.", "Walk to the back of the cave, use the Amulet of Draconic Subversion first, then talk to Emberstrife.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 4950 } },
        { 6582, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6570}, nil, "Kill Scryer, the blue dragon in the cave of Mazthoril in Winterspring, and bring his skull back to Emberstrife.", "The three 'Test of Skulls' fights can be done in any order and as a raid. Scryer (deep in the Mazthoril cave 53.2,56), cave entrance (Winterspring - Mazthoril 57,50) — you'll need to clear a fair number of elite dragonkin. ◎ Don't forget to loot the skull from all three dragons.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6583, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6570}, nil, "Kill Somnus, the green dragon in Swamp of Sorrows, and bring his skull back to Emberstrife.", "Somnus patrols a wide area in the southeast of the map (around 80,70); clear a section and wait for him to pass. He has a strong knockback, and Nature resistance helps a lot. The three trials can be done in any order; remember to touch the skull.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6584, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6570}, nil, "Kill Chronalis, the bronze dragon outside the Caverns of Time in Tanaris, and bring his skull back to Emberstrife.", "Chronalis is at the Caverns of Time entrance (64.6,50.2). The three trials can be done in any order and as a group; remember to loot the skulls.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6585, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6582, 6583, 6584}, nil, "Kill Axtroz, the red dragon in the Wetlands, and bring his skull back to Emberstrife.", "Opens only after turning in the first three Test of Skulls quests. Axtroz patrols near Grim Batol (around 85,49) and is immune to fire; skinning him requires Skinning 310.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6601, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6585}, nil, "Take the Dull Drakefire Amulet to Rexxar in Desolace.", "The quest text tells you to go back to Blackrock Spire for General Drakkisath, but the disguise amulet doesn't work inside Blackrock Spire — go straight to Rexxar in Desolace (same patrol route as in \"The Champion of the Horde\").", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "Rokaro", { xp = 4950 } },
    },

    ["kroldok_stronghold"] = {
        { 96771, "A", 37, 45, "Ranas Nightpath", "Alterac Mountains - Ruins of Dalaran 17.8,66.0", nil, false, nil, nil, "Head to Krol'dok Stronghold southeast of Riverglades and kill Zalvan Moonshadow, the high elf in league with the Twilight's Hammer.", "Given by the high elf Lanas Nightstride (17.8,66.0) in the upper level of the Ruinvivor Lounge in the Ruins of Dalaran, Alterac Mountains. Zalvan Moonshadow is inside Krol'dok Stronghold, siding with the Twilight's Hammer and misusing arcane knowledge in their service.", {{37,1}, {41,2}, {43,3}, {48,4}, {57,5}}, nil, nil, 268425, "Ranas Nightpath", { xp = 11500, money = 6500, rep = { { 2740, 250, "Kirin Tor" }, { 2826, 150, "Iron Horse Brotherhood" } } } },
        { 94980, "A", 38, 41, "Starts from the item [Krodedor Casting]", nil, nil, true, nil, nil, "Find someone inside Krol'dok Stronghold who might recognize this mold.", "The Krol'dok Casting drops from the mob 'Tunk' after the second boss; looting it starts the quest (it looks like a key mold). Return it to Alphonse Dumas at Farholde Keep, who then gives 'Key Supplies'.", {{38,1}, {39,2}, {44,3}, {52,4}}, {267138}, nil, nil, nil, { xp = 3300, money = 5500 } },
        { 94981, "A", 38, 41, "Alphonse Dumas", "Riverglades - Farholde Keep 64.4,82.0", nil, false, {94980}, { 267089 }, "Bring 4 Thick Leather and 12 Iron Bars to Alphonse Dumas at Farholde Keep.", "Prerequisite \"Krol'dok Castings\": thick leather and iron bars from the auction house or via Skinning/Mining; Duma casts a key from the mold.", {{38,1}, {39,2}, {44,3}, {52,4}}, {4304, 3575}, nil, 259250, "Alphonse Dumas", { xp = 3300, money = 5500 } },
        { 94982, "A", 40, 45, "Commander Brant", "Riverglades 66.6,81.0", "Farholde Keep three-part prerequisite: 'Saving Sunlit Woods' (Commander Brant 66.6,81.0) + 'Shards of Knowledge' and 'A Curious Trinket' (Ash Emberhold 66.7,81.0) — this quest only opens after all three are done", false, nil, {279852, 279853, 279480}, "Infiltrate Krol'dok Stronghold and bring back proof that the leader Mogg has been slain.", "Given by Commander Brant (Demar Brant, Riverglades 66.6,81.0); the Eye of Mugg drops from the stronghold boss Overlord Mugg.", {{40,1}, {41,2}, {43,3}, {48,4}, {57,5}}, {267086}, nil, 257558, "Commander Brant", { xp = 11500, money = 13000, rep = { { 2826, 150, "Iron Horse Brotherhood" } } } },
        { 94983, "A", 38, 42, "Sergeant Riftan", "Riverglades 30.6,49.1", "Farholde Keep three-part prerequisite: 'Saving Sunlit Woods' (Commander Brant 66.6,81.0) + 'Shards of Knowledge' and 'A Curious Trinket' (Ash Emberhold 66.7,81.0) — this quest only opens after all three are done", false, {94890}, nil, "Collect 8 Twilight Bracelets from Twilight's Hammer members inside Krol'dok Stronghold.", "Given by Sergeant Riftan (Riverglades 30.6,49.1); the Twilight Bracelets drop from Twilight's Hammer members in the stronghold (guaranteed from the boss, Twilight Commander Zarmok).", {{38,1}, {40,2}, {45,3}, {53,4}}, {267234}, nil, 258023, nil, { xp = 10200, rep = { { 2826, 150, "Iron Horse Brotherhood" } } }},
        { 94984, "A", 39, 44, "Ash Emberhold", "Riverglades 66.7,81.0", "Farholde Keep three-part prerequisite: 'Saving Sunlit Woods' (Commander Brant 66.6,81.0) + 'Shards of Knowledge' and 'A Curious Trinket' (Ash Emberhold 66.7,81.0) — this quest only opens after all three are done", false, {94907}, {279854, 279855}, "Defeat Nagug inside Krol'dok Stronghold and retrieve the Twilight Codex.", "Given by Ash Emberhold (Riverwood 66.7,81.0); the Twilight Codex drops from the keep's boss Nar'gurk, watch your loot after the kill.", {{39,1}, {40,2}, {42,3}, {47,4}, {56,5}}, {267104}, nil, 257591, "Ash Emberhold", { xp = 11050, rep = { { 2826, 150, "Iron Horse Brotherhood" } } } },
        { 94973, "H", 38, 41, "Starts from the item [Krodedor Casting]", nil, nil, true, nil, nil, "Find someone in Rog'mar who might recognize this mold.", "The Horde side starts with the 'Krol'dok Casting': it drops from the mob 'Tunk' after the second boss, and looting it starts the quest. Return it to Kreza Darkthorn at Rog'mar (59.8,46.0), who then gives 'Key Supplies'.", {{38,1}, {39,2}, {44,3}, {52,4}}, {267137}, nil, nil, nil, { xp = 3300, money = 5500 } },
        { 94974, "H", 38, 41, "Kreza Darkthorn", "Riverglades - Rog'mar 59.8,46.0", nil, false, {94973}, { 267089 }, "Bring 4 Thick Leather and 12 Iron Bars to Kreza Darkthorn in Rog'mar.", "Prerequisite 'Krol'dok Casting': get the Thick Leather and Iron Bars from the Auction House or by Skinning/Mining. Darkthorn makes a key from the casting mold (the wowhead Chinese site lists her as Kreza Darkthorn).", {{38,1}, {39,2}, {44,3}, {52,4}}, {4304, 3575}, nil, 256657, "Kreza Darkthorn", { xp = 3300, money = 5500 } },
        { 94968, "H", 40, 45, "Krom'rosh", "Riverglades - Rog'mar 59.4,45.6", "Riverglades Twilight quest line: faction camp → lead to the ogres → lead to the Twilight's Shroud → return to town to unlock (includes \"Twilight Approaches\", \"Twilight Letters\", \"Teach Them Some Manners\", etc.)", false, {95278}, {279852, 279480, 279853}, "Infiltrate Krol'dok Stronghold and bring back proof that the leader Mogg has been slain.", "Accept and turn in with Krom'rosh at Rog'mar (59.4,45.6; confirmed by both the wowhead quest page map marker and the quest text 'return to Krom'rosh'). The Eye of Mugg drops from the keep boss Overlord Mugg.", {{40,1}, {41,2}, {43,3}, {48,4}, {57,5}}, {267086}, nil, 256418, "Krom'rosh", { xp = 11500, money = 13000 } },
        { 94975, "H", 38, 42, "Da'grosh", "Riverglades - Hills west of Rog'mar 33.4,38.0", nil, false, {94768}, { 267090 }, "Collect 15 Cultist Ears from Twilight's Hammer members inside Krol'dok Stronghold.", "Accept and turn in with Da'grosh — the one 'The Wayward Warrior' sends you to find in the hills west of Rog'mar; this quest only opens after you finish that. Cultist ears drop from Twilight's Hammer members in the keep (boss Twilight Commander Zalmok always drops one); the description mentions more cultists hiding in the cave to the north.", {{38,1}, {40,2}, {45,3}, {53,4}}, {267091}, nil, 258570, nil, { xp = 8200 }},
        { 94972, "H", 39, 44, "Trangul", "Riverglades 59.4,44.2", "Riverglades Twilight quest line: faction camp → lead to the ogres → lead to the Twilight's Shroud → return to town to unlock (includes \"Twilight Approaches\", \"Twilight Letters\", \"Teach Them Some Manners\", etc.)", false, {95278}, {279859, 279860}, "Retrieve the Twilight Codex from Krol'dok Stronghold.", "Given by Trangul (Rog'mar camp 59.4,44.2; wowhead's quest page lists him as both start and end — the 'Commander Aggro'gosh' used before was a Stranglethorn NPC from a mislinked guide chain). The tome drops from the keep boss Nar'gurk.", {{39,1}, {40,2}, {42,3}, {47,4}, {56,5}}, {267104}, nil, 256710, "Trangul", { xp = 11050 } },
    },
    ["blackmaw_hold"] = {
        { 92344, "A", 45, 55, "Mathrengyl Bearwalker", "Darnassus 34.8,7.4", nil, false, {92345}, nil, "Collect 10 Nordrassil Rootcaps in Blackthroat Keep and bring them to Mathrengyl Bearwalker in Darnassus.", "First get 'Beneath Nordrassil' from Commander Truesong by the Azshara flight point and turn it in to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus, to unlock this quest. Nordrassil Rootcaps only grow on the new roots underground in the keep (the old surface roots don't count); a 5-player group needs 50 total, but the keep is large and they respawn after looting. Collect 10 and bring them back to Mathrengyl Bearwalker in Darnassus.", {{45,1}, {51,2}, {53,3}, {58,4}}, {250773}, nil, 4217, nil, { xp = 11300, rep = { { 69, 150, "Darnassus" } } }},
        { 92343, "H", 45, 55, "Nara Wildmane", "Thunder Bluff 75,31", nil, false, {92346}, nil, "Collect 10 Nordrassil Rootcaps in Blackthroat Keep and bring them to Nara Wildmane in Thunder Bluff.", "First get 'Beneath Nordrassil' from Jediga in Azshara and turn it in to Nara Wildmane at Elder Rise in Thunder Bluff to unlock this quest. Nordrassil Rootcaps only grow on the new roots underground in the keep (the old surface roots don't count); a 5-player group needs 50 total, but the keep is large and they respawn after looting. Collect 10 and bring them back to Nara Wildmane in Thunder Bluff (75,31).", {{45,1}, {51,2}, {53,3}, {58,4}}, {250773}, nil, 5770, nil, { xp = 11300, rep = { { 81, 150, "Thunder Bluff" } } }},
        { 92069, nil, 45, 58, "Ogtinc", "Azshara - Ruins of Eldarath 42.4,42.6", nil, false, nil, {260213, 260214, 260215}, "Bring the Bear Claw and the Fang of the Unyielding back to Ogtinc in Azshara.", "The Claw of the Great Bear comes from Withermaw deep in the lakeside grotto; the Fang of the Unyielding comes from Bonesnout the Unyielding, who roams the valley that cuts across. Bring both back to the cliff above the Ruins of Eldarath in Azshara and give them to Ogtinc (42.4,42.6) to make a keepsake.", {{45,1}, {54,2}, {56,3}}, {249697, 249696}, nil, 8405, "Ogtinc", { xp = 12400, rep = { { 576, 150, "Timbermaw Hold" } } }},
        { 92066, nil, 47, 55, "Lorekeeper Nokk", "Azshara - Ursolan 41.4,20.0", nil, false, nil, {279891, 279892}, "Find the Totem of Ursoc and the Totem of Ursol in Blackthroat Keep and bring them to Lorekeeper Nok in Ursolan.", "Timbermaw Hold reputation must be Neutral before Loremaster Nok in Ursolan will give this quest. Both bear god totems are in Blackthroat Keep: Ursoc's is in the fifth boss's room, by the wall opposite the boss; Ursol's is by the wall outside the sixth boss's room. Watch for them as you go through the dungeon; once you have both, return to Loremaster Nok in Ursolan, Azshara (41.4,20.0).", {{47,1}, {51,2}, {53,3}, {58,4}}, {249694, 249693}, nil, 249853, "Lorekeeper Nokk", { xp = 11300, rep = { { 576, 150, "Timbermaw Hold" } } }},
        { 97173, "A", 52, 59, "Archmage Timmel", "Alterac Mountains 15.4,74.1", nil, false, nil, nil, "Retrieve a Blackthroat Ritual Totem from Blackthroat Keep.", "Accept and turn in with Archmage Timear (15.4,74.1) in the Ruins of Dalaran, Alterac Mountains. The Blackthroat Ritual Totems are carried by the strongest Blackthroat shamans, such as Elder Shaman Bloodmane.", {{52,1}, {55,2}, {57,3}}, {276893}, nil, 31439, "Archmage Timmel", { xp = 12800, money = 9000, rep = { { 2740, 300, "Kirin Tor" }, { 69, 150, "Darnassus" } } }},
        { 97198, "H", 52, 59, "Mun Earthfury", "Mulgore 33.4,22.6", nil, false, nil, nil, "Retrieve a Blackthroat Ritual Totem from Blackthroat Keep.", "Horde quest of the same name: accept and turn in with Moun Earthfury (Mulgore 33.4,22.6). The Blackthroat Ritual Totems are carried by the strongest shamans, such as Elder Shaman Bloodmane.", {{52,1}, {55,2}, {57,3}}, {276893}, nil, 259118, "Mun Earthfury", { xp = 16100, money = 9000, rep = { { 2787, 300, "Earthen Ring" }, { 81, 150, "Thunder Bluff" } } }},
        { 92070, nil, 47, 55, "Starts from the item [Feathered Charm Necklace]", nil, nil, true, nil, {249698}, "Find the owner of the Feathered Charm Necklace.", "Looting the 'Feathered Charm Necklace' inside Blackthroat Keep starts this automatically — no NPC needed. It's an item-started quest; the necklace drops from Blackthroat tribe members in the keep. Follow the quest text to return the necklace to its owner; use the quest tracker to find the turn-in NPC.", {{47,1}, {51,2}, {53,3}, {58,4}}, {249698}, nil, nil, nil, { xp = 11300, rep = { { 576, 100, "Timbermaw Hold" } } }},
        { 92065, nil, 55, 60, "Ragrol", "Azshara - Ursolan 41.4,20.0", nil, false, {86814}, {249692}, "Bring the head of Varrox Darkhoof to Gatekeeper Ragrol in Ursolan.", "Timbermaw Hold reputation must be Neutral before Gatekeeper Ragrol in Ursolan will give this long chain; you must also finish the follow-up to Ekar's 'Blackthroat Bags' (kill 15 satyrs in Azshara). Then complete 'Fidarred', 'Thinning the Ranks' and 'See You, Satyr' in Azshara, turn in 'Report to Ragrol' to Ragrol, and then do 'Timbermaw Reinforcements', 'Chieftain Bloodthroat' and 'Blackthroat Counterattack' in order before you get this quest. Go into Blackthroat Keep, kill Varrox Darkhoof for his head, and return it to Gatekeeper Ragrol in Ursolan.", {{55,1}, {56,2}, {58,3}, {60,4}}, {249692}, nil, 6651, "Ragrol", { xp = 13200, rep = { { 576, 150, "Timbermaw Hold" } } }},
        { 97327, nil, 55, 60, "Ekkar", "Azshara - Ruins of Eldarath 42.0,38.8", nil, false, nil, nil, "Enter Blackthroat Keep, retrieve 5 Blackthroat Sacks and bring them to Ekal at the Ruins of Eldarath in Azshara.", "Blackthroat Bags drop from corrupted Blackthroat brethren in the keep; collect 5. They're not bound, so you can just buy them on the Auction House if you prefer. After turning them in to Ekar at the Ruins of Eldarath in Azshara (42.0,38.8), he gives a follow-up to kill 15 satyrs in Azshara, which is one of the prerequisites for 'Reclaiming Blackthroat'.", {{55,1}, {56,2}, {58,3}}, {273050}, nil, 235903, "Ekkar", { xp = 13200, money = 9000, rep = { { 576, 150, "Timbermaw Hold" } } }},
    },
    ["shapers_terrace"] = {
        { 95924, "A", 55, 60, nil, "Ironforge 64.4,4.0", nil, false, nil, {279903, 279905}, "Kill Venomspine, along with 6 Ravasaur Matriarchs and 8 Ironhide Ravasaurs.", "The quest giver is a dwarf at the dig camp outside The Shaper's Terrace (name not yet known); Venomspine is a boss-level ravasaur, with matriarchs and ironhides in packs along the way; clear it all in one run.", {{55,1}, {56,2}, {58,3}}, nil, nil, 8256, nil, { xp = 17650, money = 9000, rep = { { 47, 100, "Ironforge" }, { 72, 50, "Stormwind City" } } }},
        { 95925, "A", 55, 60, nil, "Ironforge 64.4,4.0", nil, false, nil, {279908, 279910, 279912}, "Find five locations on The Shaper's Terrace and mark them on the survey map: the Pillar of Assimilation, the Colorless Crystal, the Western Gate, the Healing Antechamber and the Unearthed Stone Guardian.", "Taken at the same camp as \"Panic at the Dig Site\"; one loop through the dungeon covers all five locations - mark whichever you reach first.", {{55,1}, {56,2}, {58,3}}, nil, nil, 8256, nil, { xp = 17650, rep = { { 47, 100, "Ironforge" }, { 72, 50, "Stormwind City" } } }},
        { 95928, "H", 55, 60, "Mayena Landseeker", "Mulgore 34.8,22.0", nil, false, nil, {279904, 279906}, "Bring one each of the Searing Crystal, Charged Crystal, Poisonous Crystal and Damp Crystal to Mayena Landseeker.", "Mayena Landseeker wants four crystals: one each of Blazing, Charged, Toxic and Damp, all from elementals inside the keep; picked up from and turned in to the same person.", {{55,1}, {56,2}, {58,3}}, {271894, 271898, 271902, 271912}, nil, 263445, nil, { xp = 17650, rep = { { 76, 50, "Orgrimmar" }, { 2787, 100, "Earthen Ring" } } }},
        { 97049, "H", 55, 60, nil, "Undercity 47.4,72.4", nil, false, nil, {279932, 279902}, "Collect 8 Seeping Ooze Essences.", "Seeping Ooze Essence drops from the oozes in the pool next to the Achromatic Crystal, collect 8; the quest giver and turn-in are the same NPC (name not yet known, outside the platform along with \"Crystallized Elementals\").", {{55,1}, {56,2}, {58,3}}, {276235}, nil, 10136, nil, { xp = 17650, money = 9000, rep = { { 68, 100, "Undercity" }, { 76, 50, "Orgrimmar" } } }},
        { 95926, "H", 55, 60, nil, "Undercity 48.4,68.0", nil, false, nil, {279908, 279910, 279912}, "Collect a Depleted Crystal Shard near the colorless crystal.", "The Achromatic Crystal is deep on the platform; the shards are picked up from the ground near it; it's also one of the locations to mark for \"Charting the Way Forward\", so do them together.", {{55,1}, {56,2}, {58,3}}, nil, nil, 2055, nil, { xp = 6600, rep = { { 68, 100, "Undercity" }, { 76, 50, "Orgrimmar" } } }},
        { 95790, "A", 55, 60, nil, nil, nil, true, nil, nil, "Go to The Shaper's Terrace and collect 15 Half-Digested Journal Pages.", "The journal was torn apart by ravasaurs and its pages are scattered across the plateau. Looting the first page starts this quest — there's no quest giver. It completes on the spot at 15 pages, no need to leave the dungeon to turn in. The pages are common-quality quest items that stack to 20. The journal belonged to an Explorers' League adventurer; the bite marks on the cover's edge show the ravasaurs did it.", {{55,1}, {56,2}, {58,3}}, {271972}, nil, nil, nil, { xp = 17655, rep = { { 47, 100, "Ironforge" }, { 72, 100, "Stormwind" } } } },
    },
}

