function ns.EnsureDungeonQuestExtInfo()
    ns.EnsureDungeonQuestExtInfo = function() return ns.DungeonQuestExtInfo end
    if ns.DungeonQuestExtInfo then return ns.DungeonQuestExtInfo end
    ns.DungeonQuestExtInfo = {
    [203] = { lv = 30, lvStd = 33, nm = "A Taste of Their Own Medicine", npc = "Sergeant Yohwa", npcid = 733, side = "A", zone = "Stranglethorn Vale", goals = { { "o", "Kill 15 Kurzen Jungle Fighters" } }, obj = "Kill 15 Kurzen Jungle Fighters, then report to Sergeant Yohwa at the Rebel Camp in Stranglethorn Vale.", text = "Sergeant Yohwa is at the Rebel Camp in Stranglethorn Vale (38.0,3.3); given together with 'Bad Medicine': Kurzen's forces outnumber the rebels ten to one, so fight back his way — enter the eastern camp, kill 15 Jungle Fighters, and get out before reinforcements arrive.", gains = { xp = 1950, rep = { { 72, 75, "Stormwind City" } } } },
    [204] = { lv = 30, lvStd = 34, nm = "Kurzen's Medicine", npc = "Sergeant Yohwa", npcid = 733, side = "A", zone = "Stranglethorn Vale", goals = { { "i", 2633, 7 }, { "i", 2634, 1 } }, obj = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.", text = "Taken from Sergeant Yohwa together with 'The Second Rebellion': the Jungle Remedy comes from Kurzen's camp medics, and the poison herb sap is in the camp's supply crates. Turn in both before Brother Nimetz will offer 'Kurzen's Mystery'.", gains = { xp = 2700, rep = { { 72, 100, "Stormwind City" } } } },
    [205] = { lv = 30, lvStd = 40, npc = "Brother Nimetz", npcid = 739, side = "A", zone = "Stranglethorn Vale", pre = { 207 }, obj = "Collect 4 Skullsplitter Idols from Skullsplitter witch doctors and mystics and bring them to Brother Nimetz in Stranglethorn Vale.", text = "Final link of the Alliance Sunken City lead-in chain: after completing it, you can pick up \"Take Two with Water\" and \"Magic of the Sunken City\" from Lorekeeper Dibbs in Southshore (Hillsbrad Foothills 50.6,57.1).", gains = { xp = 3150, rep = { { 72, 100, "Stormwind City" } } } },
    [207] = { lv = 30, lvStd = 38, npc = "Brother Nimetz", npcid = 739, side = "A", zone = "Stranglethorn Vale", pre = { 203, 204 }, obj = "Give Brother Nimetz the rubbings from the troll tablets: Bal'lal Ruins, the Vile Reef seabed, and the Ruins of Zul'Kunda.", text = "Step 3 of the Alliance Sunken City intro chain: first turn in both of Sergeant Yohwa's 'The Second Rebellion' and 'Bad Medicine' at the Rebel Camp, then Brother Nimetz will give this rubbing quest. The first tablet is in the Bal'lal Ruins, the second on the floor of the Reef Sea, and the third and fourth are both in the Ruins of Zul'Kunda; take all the rubbings, then turn them in together.", gains = { xp = 3550, rep = { { 72, 150, "Stormwind City" } } } },
    [95786] = { lv = 30, lvStd = 40, nm = "An Acquaintance in Southshore", npc = "Brother Nimetz", npcid = 739, side = "A", zone = "Stranglethorn Vale", pre = { 205 }, obj = "Take Brother Nimetz's introduction to Southshore and speak with Loremaster Dibbs.", text = "Loremaster Dibbs at the door of the shaded inn is in Southshore, Hillsbrad Foothills (50.6,57.1); after you turn in, he gives two dungeon quests.", gains = { xp = 3150, rep = { { 72, 100, "Stormwind City" }, { 67, 100, "[UNUSED] Brother Milius" } } } },
    [95748] = { lv = 30, lvStd = 40, npc = "Kenvere (32.2,27.8)", npcid = 2519, side = "H", zone = "Stranglethorn Vale", pre = { 629 }, obj = "Hear Kenvere's Gurubashi legend, make a rubbing of the tablet at the Ruins of Zul'Kunda, then report back.", text = "Step 2 of the Grom'gol three-part chain: after finishing \"The Vile Reef\", take it from Kin'weelay, and bring the hide and charcoal north to the Ruins of Zul'Kunda for the rubbing." },
    [95770] = { lv = 30, lvStd = 40, npc = "Kenvere", npcid = 2519, side = "H", zone = "Stranglethorn Vale", pre = { 95748 }, obj = "Scout the cave mouth on the west side of the Reef Sea, then report back at Grom'gol Base Camp.", text = "Last link of the three-step Grom'gol Base Camp chain: once turned in, you can pick up the dungeon quest 'The Sunken City'." },
    [95789] = { lv = 34, lvStd = 40, npc = "Krazek", npcid = 773, zone = "Stranglethorn Vale", obj = "Collect 10 Voodoo-Infused Artifacts and bring them to Krazek in Booty Bay.", text = "Available to both factions: Krazek is on the third floor of the Booty Bay inn (27.0,77.2); the voodoo-infused artifacts drop from Brine Seer casters inside the dungeon.", rew = { 279882, 279930 }, gains = { xp = 10450, rep = { { 21, 100, "Booty Bay" }, { 470, 50, "Ratchet" }, { 369, 50, "Gadgetzan" }, { 577, 50, "Everlook" } } } },
    [95791] = { lv = 34, lvStd = 40, npc = "Krazek (27.0,77.2)", npcid = 773, zone = "Stranglethorn Vale", pre = { 95789 }, obj = "Kill Captain Dreadless and the Brineseer Coroner, then report back in Booty Bay.", text = "Available to both factions: the captain is one of the dungeon bosses and the coroners come in packs along the way; picked up from Krazek together with \"The Suspicious Brine Seers\".", rew = { 279883, 279884 }, gains = { xp = 10450, rep = { { 21, 100, "Booty Bay" }, { 369, 50, "Gadgetzan" }, { 577, 50, "Everlook" }, { 470, 50, "Ratchet" } } } },
    [97130] = { lv = 34, lvStd = 40, npc = "Archmage Timmel", npcid = 31439, side = "A", zone = "Alterac Mountains", obj = "Retrieve the Ancient Gurubashi Idol and bring it to Archmage Timmel at the Ruins of Dalaran.", text = "Timmel is in the Dalaran ruins in the Alterac Mountains (15.6,73.6); the idol drops from the Undying Marrow fight, sharing the objective with the Horde's \"Ancient Gurubashi Idol\".", gains = { xp = 10450, rep = { { 2740, 300, "Kirin Tor" }, { 72, 150, "Stormwind City" } } } },
    [17] = { rew = { 250947 }, gains = { xp = 6050, rep = { { 47, 100, "Ironforge" } } } },
    [65] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Gryan Stoutmantle (56.2,47.4)", npcid = 234, side = "A", zone = "Westfall", gains = { xp = 1350, rep = { { 72, 100, "Stormwind City" } } }, obj = "Gryan Stoutmantle asks you to go speak with Wiley in Lakeshire.", text = "Take it from Marshal Gryan Stoutmantle at Sentinel Hill in Westfall; talk to Wiley the Black at the Lakeshire inn to learn where the Defias are." },
    [132] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Wiley the Black (21.4,45.2)", npcid = 266, side = "A", zone = "Westfall", goals = { { "i", 1327, 1 } }, gains = { xp = 680, rep = { { 72, 50, "Stormwind City" } } }, obj = "Bring Wiley's Note to Gryan Stoutmantle in Westfall.", text = "Get the note from Wiley the Black in Lakeshire, then return to Marshal Gryan Stoutmantle at Sentinel Hill in Westfall." },
    [135] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Marshal Gryan Stoutmantle", npcid = 234, side = "A", zone = "Westfall", goals = { { "i", 1327, 1 } }, gains = { xp = 680, rep = { { 72, 50, "Stormwind City" } } }, obj = "Bring Wiley's Note to Mathias Shaw in Stormwind.", text = "Take Wiley's Note to Mathias Shaw of SI:7 at the barracks in Stormwind's Old Town." },
    [141] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Mathias Shaw", npcid = 332, side = "A", zone = "Westfall", goals = { { "i", 1353, 1 } }, gains = { xp = 340, rep = { { 72, 25, "Stormwind City" } } }, obj = "Bring Shaw's Report to Gryan Stoutmantle in Westfall.", text = "Once you have Shaw's Report, return to Sentinel Hill in Westfall and give it to Gryan Stoutmantle." },
    [142] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Marshal Gryan Stoutmantle", npcid = 234, side = "A", zone = "Westfall", goals = { { "i", 1381, 1 } }, gains = { xp = 1350, rep = { { 72, 100, "Stormwind City" } } }, obj = "Hunt down the Defias Messenger in Westfall and bring the letter he carries to Stoutmantle.", text = "Camp the road between Moonbrook, the Gold Coast Quarry and Jangolode Mine for the Defias Messenger; kill him and turn the letter in at Sentinel Hill." },
    [155] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "The Defias Traitor (43.1,70.2)", npcid = 467, side = "A", zone = "Westfall", gains = { xp = 1700, rep = { { 72, 150, "Stormwind City" } } }, obj = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. After the Defias Traitor leads you to the lair of VanCleef and his men, report back to Gryan Stoutmantle as soon as possible.", text = "Escort the Defias Traitor to the Defias hideout in Moonbrook; he leads the way, don't let him die; once there, report back to Stoutmantle at Sentinel Hill." },
