    [389] = { lv = 16, lvStd = 22, nm = "The Stockade Riots", npc = "Baros Alexston (49.0,30.2)", npcid = 1646, side = "A", zone = "Stormwind City", gains = { xp = 435 }, obj = "Speak with Warden Thelwater of the Stockade.", text = "For the prerequisite, finish \"The Defias Brotherhood\" chain and take it from Baros Alexston in Stormwind City; go into The Stockade and talk to Warden Thelwater." },
    [356] = { lv = 6, lvStd = 11, nm = "Patrolling the Rear", npc = "Deathguard Linnea", npcid = 1495, side = "H", zone = "Tirisfal Glades", goals = { { "o", "Kill 8 Horrid Blood Zombies" }, { "o", "Kill 8 Wandering Spirits" } }, gains = { xp = 660, rep = { { 68, 75, "Undercity" } } }, obj = "Kill 8 Horrid Blood Zombies and 8 Wandering Spirits, then report to Deathguard Linnea.", text = "Linnea is in Brill; both sets of quest mobs are just outside town, clear them and go back to turn in." },
    [447] = { lv = 9, lvStd = 12, nm = "A Deadly Recipe", npc = "Apothecary Renferrel", npcid = 1937, side = "H", zone = "Silverpine Forest", goals = { { "i", 3253, 6 }, { "i", 3254, 6 } }, gains = { xp = 910, rep = { { 68, 100, "Undercity" } } }, obj = "Collect 6 Grizzly Bear Hearts and 6 Thick Blood samples and deliver them to Master Apothecary Faranell in Undercity.", text = "Take it from Renferrel at the Sepulcher; the Grizzly Bear Hearts and Thick Blood are both from around Silverpine Forest; once you have everything, turn in to Faranell in Undercity.", rew = { 3448 } },
