    [5068] = { lv = 57, lvStd = 58, npc = "Malyfous's Catalogue", zone = "Winterspring", obj = "To craft the Breastplate of Bloodthirst, you must give Marevus Darkhammer the following: 1 Hide of the Beast, 10 Frayed Abomination Stitching, 5 Arcanite Bars, 5 Skin of Shadow.", text = "Marevus's catalog is in Winterspring (61.0,38.8). Afterward, find Marevus Darkhammer (Winterspring)." },
    [5122] = { lv = 55, lvStd = 56, npc = "Aurius", npcid = 10917, zone = "Stratholme", obj = "Retrieve the Medallion of Faith and bring it to Aurius in Stratholme.", text = "Aurius is in Stratholme." },
    [5265] = { lv = 55, lvStd = 56, npc = "Baron Maxwell Tyrosus", npcid = 11034, zone = "Eastern Plaguelands", obj = "Open the Argent Dawn chest and claim your reward.", text = "Baron Maxwell Tyrosus is in Eastern Plaguelands (81.4,58.0)." },
    [5342] = { lv = 52, lvStd = 56, npc = "Alexi Barov", npcid = 11022, zone = "Tirisfal Glades", obj = "Go to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Bring his head to Alexi Barov.", text = "Alexi Barov is in Tirisfal Glades (83.0,71.4)." },
    [5344] = { lv = 52, lvStd = 56, npc = "Weldon Barov", npcid = 11023, zone = "Western Plaguelands", obj = "Go to the Bulwark - Horde territory - and assassinate Alexi Barov. Bring his head to Weldon Barov.", text = "Weldon Barov is in Western Plaguelands (43.4,83.4)." },
    [6804] = { lv = 55, lvStd = 59, npc = "Duke Hydraxis", npcid = 13278, zone = "Azshara", obj = "Use the Water of Neptulon on Tainted Water Elementals in the Eastern Plaguelands. Bring 12 Discordant Bracers and the Water of Neptulon to Duke Hydraxis in Azshara.", text = "Duke Hydraxis is in Azshara (79.2,73.4)." },
    [7483] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7481, 7482}, obj = "Bring a Libram of Rapidity, 1 Primal Black Diamond, 2 Large Brilliant Shards and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", text = "Lorekeeper Lydros is in Dire Maul.", gains = { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } } },
    [7484] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7481, 7482}, obj = "Bring a Libram of Focus, 1 Primal Black Diamond, 4 Large Brilliant Shards and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", text = "Lorekeeper Lydros is in Dire Maul.", gains = { xp = 3300, rep = { { 809, 200, "Shen'dralar" } } } },
    [7485] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7481, 7482}, obj = "Hand the Libram of Protection, 1 Primal Black Diamond, 2 Large Brilliant Shards and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul in exchange for an Arcanum of Protection.", text = "Lorekeeper Lydros is in Dire Maul.", gains = { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } } },
    [7509] = { lv = 60, lvStd = 63, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", obj = "You must get Onyxia to breathe fire on this Unfired Ancient Blade. Once done, pick up the Heated Ancient Blade. Be aware that the Heated Ancient Blade won't stay heated forever — time is very short.", text = "Lorekeeper Lydros is in Dire Maul." },
    [7638] = { lv = 60, lvStd = 63, npc = "Duthorian Rall", npcid = 6171, zone = "Stormwind City", obj = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", text = "Duthorian Rall is in Stormwind City (39.4,30.6). Afterwards, go see Lord Grayson Shadowbreaker (Stormwind City)." },
    [8996] = { lv = 58, lvStd = 63, npc = "Spirit of Lord Valthalak", npcid = 16073, zone = "Dire Maul: North", obj = "Return to Bodley in Blackrock Mountain and give him the Summoning Brazier.", text = "Spirit of Lord Valthalak is in Dire Maul: North. When done, go find Bodley." },
    [92345] = { lv = 45, lvStd = 55, npc = "Commander Truesong", npcid = 239822, side = "A", zone = "Azshara", obj = "Go to the Cenarion Enclave in Darnassus and speak with Mathrengyl Bearwalker.", text = "Beneath Nordrassil series (Alliance), step 1: Commander Truesong by the Azshara flight point (11.8,78.2). Then go to the Cenarion Enclave in Darnassus and turn in to Mathrengyl Bearwalker (35.4,8.4), who then gives 'Getting to the Root'." },
    [92346] = { lv = 45, lvStd = 55, npc = "Jedija", npcid = 8587, side = "H", zone = "Azshara", obj = "Go to Elder Rise in Thunder Bluff and speak with Nara Wildmane.", text = "First link of the Beneath Nordrassil series (Horde): Jediga is in Azshara (22.6,51.4); after accepting, turn in to Nara Wildmane at Elder Rise in Thunder Bluff (75.7,31.6), then pick up \"Tracing the Roots\"." },
    [94907] = { lv = 36, lvStd = 44, npc = "Ash Emberhold", npcid = 257591, side = "A", zone = "Riverglades", obj = "Capture a Twilight cultist in the Riverglades and bring it back to Ash Emberhold at Farholde Keep.", text = "Step 1 of the Riverwood introduction series (two steps): Ash Emberhold is at Farholde Keep (66.6,81.0); both pickup and turn-in are with her." },
    [94997] = { lv = 38, lvStd = 42, npc = "Sergeant Riftan", npcid = 258023, side = "A", zone = "Riverglades", pre = { 94983 }, obj = "Collect the Cursed Relic Pack and bring it to Ash Emberhold at Farholde Keep.", text = "Second of the three-part Riverglades intro chain: take it from Sergeant Riftan in Riverglades (30.6,49.0); once you've gathered the Bag of Cursed Relics, return to Farholde Keep and turn it in to Ash Emberhold (66.6,81.0).", gains = { xp = 3450, money = 5500 } },
    [95196] = { lv = 48, lvStd = 53, nm = "Watch Your Back!", npc = "Sally McCleary", npcid = 260146, side = "A", zone = "Dustwallow Marsh", pre = {95194}, obj = "Go to Dustwallow Marsh to meet up with Sally McCleary and learn more about the task.", text = "Taken at the Theramore inn; head out of town and around behind the graveyard to meet Sully, and turn in at the town gate (63.4,42.4).", gains = { xp = 1300, rep = { { 72, 75, "Stormwind City" } } } },
    [95198] = { lv = 48, lvStd = 53, nm = "The King Returns?", npc = "Sally McCleary", npcid = 260271, side = "A", zone = "Dustwallow Marsh", pre = {95196}, obj = "Use the SI:7 Disguise Kit to eavesdrop on Jaina and her confidants in the Theramore mage tower.", text = "Accept at the Theramore gate, take the SI:7 Disguise Kit (269000) into the mage tower: disguise yourself as a marine to relieve the guard, stand in position and listen to Jaina's secret conversation, then cancel the disguise and turn in at the gate. This unlocks both 'The Secret Prison' and 'Wet Work'.", gains = { xp = 1300, rep = { { 72, 100, "Stormwind City" } } } },
    [95263] = { lv = 48, lvStd = 53, nm = "Grave News", npc = "Sally McCleary", npcid = 260271, side = "A", zone = "Dustwallow Marsh", pre = {95262, 96335}, obj = "Return to Dustwallow Marsh and report to Sally McCleary.", text = "Automatically follows from \"The Secret Prison\" or \"Prisoner in Chains\"; return to Sally McCleary at the Theramore city gate (63.4,42.4) to turn in, and she then gives \"A Matter of Importance\".", gains = { xp = 2860, rep = { { 72, 75, "Stormwind City" } } } },
    [95264] = { lv = 48, lvStd = 53, nm = "A Matter of Great Import", npc = "Mathias Shaw", npcid = 332, side = "A", zone = "Stormwind City", pre = {95263}, obj = "Deliver the intelligence in person to Mathias Shaw in Stormwind.", text = "Return to SI:7 in Stormwind's Old Town and turn in to Mathias Shaw (78.3,70.7); this wraps up the Alliance main storyline.", gains = { xp = 1300, money = 8000, rep = { { 72, 100, "Stormwind City" } } } },
    [95309] = { lv = 48, lvStd = 53, nm = "Not One Orc Left Behind", npc = "Sergeant Urka", npcid = 260383, side = "H", zone = "Prison of Alcaz", pre = {95285}, obj = "Enter the Prison of Alcaz and find Commander Forka.", text = "Given by Sergeant Ulka at the camp near the shore of Alcaz Island (70.3,19.1); once inside the dungeon, find Commander Folka.", gains = { xp = 1300 } },
    [96369] = { lv = 48, lvStd = 53, nm = "Bad News for Forka", side = "H", zone = "Prison of Alcaz", pre = {95454}, obj = "Return to Commander Forka.", text = "Picked up from \"The Glory of Kukalon\" and turned in to Commander Folka; after turning in, next up is \"The Warchief Must Know\".", gains = { xp = 1300 } },
    [96377] = { lv = 48, lvStd = 53, nm = "State Secrets", npc = "'Razor' Rejik", npcid = 6946, side = "A", zone = "Stormwind City", pre = {96337}, obj = "Bring the document box back to Stormwind.", text = "Bring the document box back to \"Razor\" Rezik at SI:7 in Stormwind's Old Town (78.3,71.1); Rixxie Hijinks in Booty Bay also accepts the same box, and both pay the same.", gains = { xp = 6550, rep = { { 76, 150, "Orgrimmar" } } } },
    [96337] = { lv = 48, lvStd = 53, nm = "Worth More Than Gold", npc = "Mason Connolly", side = "A", zone = "Westfall", pre = {96335}, obj = "Follow Mason Connolly's note to find the treasure he hid.", text = "After taking this inside the instance, leave first: go to Moonbrook in Westfall, click the wooden plank behind the chest on the inn's second floor to complete, and turn it in on the spot for the document box (274041).", gains = { xp = 11550 } },
    [95483] = { lv = 48, lvStd = 53, nm = "The Warchief Must Know", side = "H", zone = "Orgrimmar", pre = {96369}, obj = "Bring word of Varian Wrynn's whereabouts back to Thrall in Orgrimmar.", text = "The end of the Horde line: follows \"Bad News for Forka\"; bring the news back to Thrall in Orgrimmar's Valley of Wisdom (31.7,37.8) to turn in; an errand outside the dungeon, no need to go inside.", gains = { xp = 2405, rep = { { 76, 100, "Orgrimmar" } } } },
    [95285] = { lv = 48, lvStd = 53, nm = "A Twist of Fate", npc = "Sergeant Urka", npcid = 260383, side = "H", zone = "Dustwallow Marsh", pre = {95284}, obj = "Talk to Sergeant Urka to learn about the situation on Alcaz Island.", text = "Kukalon Sergeant Urka is in the camp near the shore of Alcaz Island (70.3,19.1) and is both quest giver and turn-in; turning it in opens \"An Eye for an Eye\" and \"Blood-Red Bandanas\".", gains = { xp = 1300, money = 2000, rep = { { 76, 75, "Orgrimmar" } } } },
    [95284] = { lv = 48, lvStd = 53, nm = "The Best of the Best", side = "H", zone = "Dustwallow Marsh", obj = "Find the missing Kukalon elites.", text = "First link of the Horde line, taken at the Kukalon camp near the shore of Alcaz Island; after turning in, next up is \"A Twist of Fate\".", gains = { xp = 1300, rep = { { 76, 75, "Orgrimmar" } } } },
    [95194] = { lv = 48, lvStd = 53, nm = "Inside Man in Theramore", npc = "Mathias Shaw", npcid = 332, side = "A", zone = "Stormwind City", obj = "Find Shaw's agent in Theramore.", text = "SI:7 headquarters is in Old Town, Stormwind City (78.3,70.7); accept from Mathias Shaw. Turn in at the corner of the inn on Theramore Isle to the dwarf agent Sally McCleary (63.4,42.4), who then gives 'Watch Your Back!'.", gains = { xp = 1300, rep = { { 72, 25, "Stormwind City" } } } },
    [95454] = { lv = 48, lvStd = 53, nm = "Glory of Kukalon", side = "H", pre = {95309}, zone = "Prison of Alcaz", obj = "Learn the whereabouts of Varian Wrynn, and read the note on the ground.", text = "Step 1 of the Horde Prison of Alcaz introduction chain: enter the Prison of Alcaz, find Varian Wrynn and read the note on the ground; then bring the news back to Thrall in Orgrimmar.", gains = { xp = 12100, rep = { { 76, 100, "Orgrimmar" } } } },
    [96775] = { lv = 42, lvStd = 46, npc = "Mazu'kon", npcid = 264074, side = "H", zone = "Mulgore", obj = "Go deep into Zul'Farrak, kill Witch Doctor Zum'rah and bring back his head intact.", text = "Both pickup and turn-in are with Mazukon in Mulgore (32.5,20.7): take the quest first, then go into Zul'Farrak, kill Witch Doctor Zum'rah and bring his head back.", gains = { xp = 10100, money = 6500 } },
    [96776] = { lv = 43, lvStd = 51, npc = "Onaana Swift Hoof", npcid = 268557, side = "H", zone = "Mulgore", obj = "Recover the crystal known as An'she's Radiance from Maraudon and bring it back to Onaana Swift Hoof.", text = "Take it from Onaana Swift Hoof in Mulgore (32.6,24.0); Anther's Radiance is a crystal inside Maraudon; bring it back to her.", gains = { xp = 11900, money = 7500 } },
    [97197] = { lv = 46, lvStd = 55, npc = "Alana Stormwalker", npcid = 259119, side = "H", zone = "Mulgore", obj = "Retrieve a Fragment of the Firelands from Blackrock Depths and bring it to Alana Stormwalker.", text = "Take it from Arra'chea Stormwalker in Mulgore (33.4,22.4); the Firelands shard drops in Blackrock Depths; bring it back to her.", gains = { xp = 14800, money = 8500 } },
    [92914] = { lv = 35, lvStd = 43, nm = "The Strange Pylon", npc = "Shen'dralar Pylon (43.8,34.3)", zone = "Shen'dralar", si = true, obj = "Explore Shen'dralar and look for other pylons like the one you saw.", text = "The head of the Shen'dralar line: started by looting near the crystal tower in the open world (object-started), and turned in on the spot to Mordant Evershade at the temple (35.1,46.4).", gains = { xp = 3600 } },
    [96010] = { lv = 35, lvStd = 41, nm = "Crystal Pylon Shard", npc = "Mordant Evershadow (35.1,46.4)", npcid = 253471, zone = "Shen'dralar", pre = { 92914 }, obj = "Retrieve the closely guarded crystal tower shards and fragments from Sengras Village and Gelkis Village and bring them to Mordant Evershade.", text = "The centaurs carried the shards back as spoils to the villages of Shengras and Gelkis, both guarded; once you have them all, return to the temple and turn in to Mordant Evershade.", gains = { xp = 2450 } },
    [96018] = { lv = 35, lvStd = 43, nm = "Powering the Pylon", npc = "Mordant Evershadow (35.1,46.4)", npcid = 253471, zone = "Shen'dralar", pre = { 96010 }, obj = "Get the mana filter from inside the Shen'dralar temple, use it to collect ancient mana crystals, charge the crystal tower, then report to Mordant Evershade.", text = "The charge isn't a mob drop: find an Unstable Mana Rift — blue floating orbs spray out near the rift; walk over an orb to absorb it automatically. Feed each tower 4 orbs, 8 total for the two towers; once both are full, report back to Mordant.", gains = { xp = 3600 } },
    [93016] = { lv = 35, lvStd = 43, nm = "A Brief History Lesson", npc = "Mordant Evershadow (35.1,46.4)", npcid = 253471, zone = "Shen'dralar", pre = { 96018 }, obj = "Talk to Mordant Evershadow in Shen'dralar to learn about the crystals you repaired.", text = "Pure dialogue step: return to the temple and listen to Mordant Evershade explain the Shen'dralar's origins; right after turning in comes \"Meeting the Magister\".", gains = { xp = 360 } },
    [93394] = { lv = 35, lvStd = 43, nm = "Meeting the Magister", npc = "Mordant Evershadow (35.1,46.4)", npcid = 253471, zone = "Shen'dralar", pre = { 93016 }, obj = "Find Magister Kirandis inside the Shen'dralar Temple.", text = "Go deep into the temple and talk to Magister Kirandis (47.4,76.2); don't pull random mobs in the temple.", gains = { xp = 360 } },
    [93341] = { lv = 35, lvStd = 43, nm = "The Abandoned Garden", npc = "Mithera (53.2,75.9)", npcid = 254578, zone = "Shen'dralar", pre = { 93394 }, obj = "Investigate the abandoned garden near Shen'dralar, then report back to Mithera at the nearby temple.", text = "Mithras is outside the temple (53.2,75.9); check the Abandoned Garden to the southeast and report back; after turning in you can take \"Rumors in the Woods\".", gains = { xp = 1800 } },
    [93594] = { lv = 35, lvStd = 43, nm = "Whispers in the Woods", npc = "Mithera (53.2,75.9)", npcid = 254578, zone = "Shen'dralar", pre = { 93341 }, obj = "Go to the Forgotten Garden in the southeast corner of Shen'dralar and find the treant Woodfiend.", text = "Shen'dralar is a new zone in the southeast corner of Desolace, bordering Feralas and Mulgore, and is a separate map in the client. Accept from Mithera outside the temple (53.2,75.9), then head southeast to the Forgotten Garden to find the treant (69.7,71.8) and turn in on the spot; he then asks you to go into Maraudon for the Waters of Earthsong (continues with 'Rot and Remorse').", gains = { xp = 360 } },
    [93404] = { lv = 35, lvStd = 49, nm = "Decay and Regret", npc = "Woodfiend (69.7,71.8)", npcid = 254674, zone = "Shen'dralar", pre = { 93594 }, goals = { { "i", 272186, 1 }, { "i", 272187, 1 } }, obj = "Retrieve the Earthsong Water and extinguish the Woodfiend.", text = "Accept in the Forgotten Garden of Shen'dralar; after accepting, talk to the tree NPC next to it to open the follow-up. The water vial is in Maraudon: after killing the princess, jumping down the waterfall and killing Rotgrip, there's an obvious water orb on the water surface on the way toward the goblin boss — right-click it to take it. Turn in to the treant in the Forgotten Garden of Shen'dralar (69.7,71.8); extinguishing the flames is just a click once you're back.", gains = { xp = 11100 } },
    [93606] = { lv = 35, lvStd = 45, nm = "A Screaming Breakup", npc = "Cogswug the Brave (72.5,31.5)", npcid = 253527, zone = "Shen'dralar", pre = { 93604 }, obj = "Bring Kurga the Bouquet of Mercy and the Venomous Blood of Agamaggan to settle the dispute among the quilboar.", text = "Given by Kogsug after turning in 'Blood of Agamaggan'. Pick the bouquet flowers back in Shen'dralar's Forsaken Garden; the blood is the one you brought back from Razorfen Downs in the previous step. Bring both to his mate, Wise Kulga, and she'll trade the necklace for them. Turning in leads straight to 'The Forgotten Necklace'.", gains = { xp = 3900 } },
    [93609] = { lv = 35, lvStd = 45, nm = "The Forgotten Necklace", npc = "Mithera (53.2,75.9)", npcid = 254578, zone = "Shen'dralar", pre = { 93606 }, obj = "Bring the Forgotten Necklace to Mithera at the Shen'dralar Temple in Desolace.", text = "Taken directly after turning in \"A Screaming Breakup\"; the magic in the necklace is spent; take it back to Mithras at the Shen'dralar temple, turnable just outside; this ends the line.", gains = { xp = 4850, money = 13000 } },
    [93601] = { lv = 35, lvStd = 45, nm = "Passing the Buck", npc = "Woodfiend (69.7,71.8)", npcid = 254674, zone = "Shen'dralar", pre = { 93404 }, obj = "Head north to Bristleback Refuge in Desolace and talk to a quilboar of some standing.", text = "The treant insists the quilboars stole the lady's gift and sends you to Bristleback Refuge to question them: the target is Kogsug the Brave in the refuge (72.5,31.5). Turning in to him conveniently gives 'Blood of Agamaggan'.", gains = { xp = 390, money = 600 } },
    [92065] = { lv = 55, lvStd = 60, nm = "Reclaiming Blackthroat", npc = "Ragrol", npcid = 6651, zone = "Azshara", pre = { 86814 }, goals = { { "i", 249692, 1 } }, obj = "Bring the head of Varrox Darkhoof to Gatekeeper Ragrol in Ursolan.", text = "End of the long Timbermaw Hold chain: enter Blackthroat Keep, kill Varrox Darkhoof for his head, and turn it in to Ragrol in Ursolan.", gains = { xp = 13200, rep = { { 576, 150, "Timbermaw Hold" } } } },
    [86814] = { lv = 55, lvStd = 58, nm = "Blackthroat Counterattack", npc = "Ragrol", npcid = 6651, zone = "Azshara", pre = { 87346 }, obj = "Deal with the Blackthroat counterattack.", text = "Timbermaw Hold chain, step 5; once turned in, pick up 'Reclaiming Blackthroat'.", gains = { xp = 7050, rep = { { 576, 150, "Timbermaw Hold" } } } },
    [87346] = { lv = 55, lvStd = 58, nm = "Chieftain Bloodthroat", npc = "Ragrol", npcid = 6651, zone = "Azshara", pre = { 86798 }, goals = { { "i", 236631, 1 } }, obj = "Retrieve the Bloodthroat Crusher.", text = "Timbermaw Hold chain, step 4.", gains = { xp = 5650, rep = { { 576, 100, "Timbermaw Hold" } } } },
    [86798] = { lv = 55, lvStd = 58, nm = "Timbermaw Reinforcements", npc = "Ragrol", npcid = 6651, zone = "Timbermaw Hold", pre = { 86797 }, obj = "Reinforce Timbermaw Hold.", text = "Timbermaw Hold chain, step 3.", gains = { xp = 560, rep = { { 576, 50, "Timbermaw Hold" } } } },
    [86797] = { lv = 53, lvStd = 56, nm = "Report to Ragrol", npc = "Ragrol", npcid = 6651, zone = "Azshara", pre = { 86777, 86792, 86796 }, obj = "Report to Gatekeeper Ragrol.", text = "Timbermaw Hold chain, step 2: only available after all three prerequisites are done.", gains = { xp = 530, rep = { { 576, 25, "Timbermaw Hold" } } } },
    [86777] = { lv = 53, lvStd = 56, nm = "Fedarad", zone = "Azshara", obj = "Complete Fedarad's quests in Azshara.", text = "One of the three parallel prerequisites of the Timbermaw Hold chain." },
    [86792] = { lv = 55, lvStd = 58, nm = "Thinning the Ranks", zone = "Azshara", obj = "Thin the Blackthroat ranks in Azshara.", text = "One of the three parallel prerequisites of the Timbermaw Hold chain." },
    [86796] = { lv = 55, lvStd = 58, nm = "See You Later, Satyr", zone = "Azshara", obj = "Deal with the satyrs in Azshara.", text = "One of the three parallel prerequisites of the Timbermaw Hold chain." },
    [9240] = { lv = 40, lvStd = 50, nm = "Mallet of Zul'Farrak", npc = "Guardian Chilga", zone = "Hinterlands", si = true, opt = true, elite = true, rew = { 9240 }, obj = "Go to the Altar of Zul in The Hinterlands, kill Qiaga the Keeper and loot the Sacred Mallet, then use it at the top altar of Jintha'Alor to turn it into the Mallet of Zul'Farrak.", text = "Optional quest — skipping it doesn't affect the dungeon's main storyline. The Altar of Zul is in The Hinterlands (48,67); Qiaga the Keeper respawns every 5 minutes and there are 2 elites on top of the altar — clear them together. With the Sacred Mallet in hand, fight your way to the very top of Jintha'Alor, find the altar where the Broken-Tooth Elder lies, and right-click the Sacred Mallet in your bags; when the cast finishes it becomes the Mallet of Zul'Farrak." },

    [93786] = { lv = 35, lvStd = 36, nm = "A Bloody Warning", npc = "Krom'rosh", npcid = 256418, side = "H", zone = "Riverglades", obj = "Kill 12 Meadowbrook Farmhands, then bring news of your victory to Krom'rosh.", text = "Given by Kromrosh in Logmar, taken together with \"Easy Pickings\"; the targets are the farmhands at Meadow Creek Farm, who spawn in groups around the farm; turn in at Logmar when done." },
    [93787] = { lv = 36, lvStd = 36, nm = "Easy Pickings", npc = "Krom'rosh", npcid = 256418, side = "H", zone = "Riverglades", obj = "Steal 6 Feed Sacks from the Alliance farm at Meadowbrook, then report to Krom'rosh.", text = "Same batch as \"A Bloody Warning\"; steal feed sacks from the Alliance farm at Meadow Creek; Kromrosh only gives \"Teach Them a Lesson\" after both are turned in." },
    [94483] = { lv = 36, lvStd = 39, nm = "Teach Them Some Manners", npc = "Krom'rosh", npcid = 256418, side = "H", zone = "Riverglades", pre = { 93786, 93787 }, obj = "Kill 8 Farholde Priests and 12 Farholde Scouts south of the river.", text = "Opens only after the first two are turned in; the targets are around Farholde south of Riverglades - clear them with the priest and scout." },
    [94672] = { lv = 36, lvStd = 41, nm = "Twilight Approaches", npc = "Trangul", npcid = 256710, side = "H", zone = "Riverglades", pre = { 94483 }, obj = "Kill 8 Twilight Raiders and 8 Twilight Neophytes in the Sunlit Woods for Trangul of Rog'mar.", text = "Given by Trangul of Rog'mar, in the same batch as \"Twilight Letters\"; the Twilight Raiders and Neophytes are all around the Sunlit Woods." },
    [94680] = { lv = 36, lvStd = 41, nm = "Twilight Correspondence", npc = "Trangul", npcid = 256710, side = "H", zone = "Riverglades", pre = { 94483 }, obj = "Take 3 Twilight Letters from Twilight Shadowmages in the Sunlit Woods for Trangul of Rog'mar.", text = "Same batch as \"The Twilight Approaches\"; the letters drop from Twilight Shadowmages, collect 3; Trangul only gives \"Digging for Answers\" after both are turned in." },
    [94727] = { lv = 36, lvStd = 40, nm = "Digging for Answers", npc = "Trangul", npcid = 256710, side = "H", zone = "Riverglades", pre = { 94672, 94680 }, obj = "Persuade a Twilight's Hammer miner in Sunlit Woods to spill his secrets.", text = "Trangul gives this only after both are turned in; go to the Sunlit Woods and persuade the Twilight's Hammer miners to talk, then on the way back turn in the result to Clubtoe in the Sunlit Woods." },
