    [95601] = { lv = 36, lvStd = 40, nm = "The Purple Guy", npc = "Twilight Brute", npcid = 261208, side = "H", zone = "Riverglades", pre = { 95417 }, obj = "Kill 5 Empowered Brutes and 10 Twilight Ritualists, then return to Clubtoe in the Sunlit Woods.", text = "Picks up from the first half: clear Empowered Brutes and Twilight Ritualists in the caves, then return to Clubtoe in Sunlit Woods." },
    [95602] = { lv = 36, lvStd = 40, nm = "A Sickening Light", npc = "Clubtoe", npcid = 260931, side = "H", zone = "Riverglades", pre = { 94727 }, obj = "Destroy 5 Twilight Ritual Circles found in the caves beneath Sunlit Woods.", text = "Runs in parallel with \"The Purple Guy\": destroy the Twilight ritual circles in the cave, 5 in total." },
