    [95418] = { lv = 36, lvStd = 40, nm = "Spreading the Word", npc = "Clubtoe", npcid = 260931, side = "H", zone = "Riverglades", pre = { 95427 }, obj = "Bring Jogg's Insignia to Trangul in Rog'mar.", text = "Bring Jog's insignia back to Trangul in Rog'mar; this one leads you on to the ogre city to the north." },
    [95420] = { lv = 36, lvStd = 40, nm = "Land of Giants", npc = "Trangul", npcid = 256710, side = "H", zone = "Riverglades", pre = { 95418 }, obj = "Bring Jogg's Insignia to the ogre city in the north.", text = "Trangul has you deliver the insignia to Krugfist in Boulderrock, the ogre city to the north." },
    [95424] = { lv = 36, lvStd = 41, nm = "Might Makes Right", npc = "Krugfist", npcid = 255829, side = "H", zone = "Riverglades", pre = { 95420 }, obj = "Kill 7 Twilight Tormentors and 7 Twilight Flamecallers for Krugfist of Boulderrock.", text = "Given by Krugfist of Boulderrock: clear the Twilight Tormentors and Firecallers in the cave; same batch as \"The Unworthy Champion\"." },
    [95425] = { lv = 36, lvStd = 42, nm = "An Unworthy Champion", npc = "Krugfist", npcid = 255829, side = "H", zone = "Riverglades", pre = { 95420 }, obj = "Recover the Skull Crusher from Kronk for Krugfist of Boulderrock.", text = "Same batch as 'Might Makes Right'; take back the Skull Crusher from Kronk." },
    [94745] = { lv = 38, lvStd = 44, nm = "Cutting a Bloody Path", npc = "Da'grosh", npcid = 258570, side = "H", zone = "Riverglades", pre = { 94744 }, obj = "Defeat 8 Twilight Zealots, 8 Twilight Corruptors and 8 Twilight Champions within the Twilight's Shroud for Da'grosh.", text = "Da'grosh is in the hills west of Rog'mar; this is one branch of the Twilight's Shroud clearing line - 8 each of Zealots, Corruptors and Champions." },
    [94748] = { lv = 38, lvStd = 44, nm = "Breaking the Chains", npc = "Da'grosh", npcid = 258570, side = "H", zone = "Riverglades", pre = { 94744 }, obj = "Free 5 Rog'mar Scouts inside the Twilight's Shroud for Da'grosh.", text = "Same batch as \"Fight Our Way Out\": rescue 5 Rog'mar scouts in the Twilight's Shroud; \"Bring Me His Head\" opens only after both are turned in." },
    [94768] = { lv = 38, lvStd = 46, nm = "Bring Me Their Heads", npc = "Da'grosh", npcid = 258570, side = "H", zone = "Riverglades", pre = { 94745, 94748 }, obj = "Defeat Overlord Kilgar in the Twilight's Shroud and bring his insignia to Da'grosh.", text = "Opens only after the first two are turned in; defeat Overlord Kilgar in the Twilight's Shroud and bring his insignia back to Da'grosh." },
    [95278] = { lv = 38, lvStd = 45, nm = "It's Time, Brother...", npc = "Da'grosh", npcid = 258570, side = "H", zone = "Riverglades", pre = { 94768 }, obj = "Deliver the missive to Krom'rosh at Rog'mar.", text = "Da'grosh has you carry a letter back to Krom'rosh in Rog'mar; only after turning in do \"The Eye of Mog\" and \"The Twilight Codex\" open." },
    [95428] = { lv = 36, lvStd = 41, nm = "Krugfist's Decree", npc = "Krugfist", npcid = 255829, side = "H", zone = "Riverglades", pre = { 95424, 95425 }, obj = "Report to Krom'rosh in Rog'mar.", text = "Bring Krugfist's decree back to Krom'rosh in Rog'mar; only after this turn-in will he give you \"The Wayward Warrior\"." },
    [94744] = { lv = 38, lvStd = 43, nm = "The Wayward Warrior", npc = "Krom'rosh", npcid = 256418, side = "H", zone = "Riverglades", pre = { 95428 }, obj = "Find Da'grosh in the hills west of Rog'mar.", text = "Krom'rosh sends you to the mountains west of Rog'mar to find Dagrosh; this is the lead-in quest toward the Twilight's Shroud, turned in to Dagrosh, and only afterward does he give \"Cut a Bloody Path\" and \"Sever the Chains\"." },
    [94879] = { lv = 36, lvStd = 40, nm = "Fragments of Knowledge", npc = "Ash Emberhold", npcid = 257591, side = "A", zone = "Riverglades", obj = "Collect 5 Twilight Pages in the Sunlit Woods and bring them to Ash Emberhold at Farholde Keep.", text = "Given by Ash Emberhold at Farholde Keep: collect 5 Twilight Pages from the Sunlit Woods; with \"A Curious Trinket\" and \"Save the Sunlit Woods\" it forms the Farholde Keep trio, and is also one of the unlock conditions for \"Eye of Mugg\"." },
    [94881] = { lv = 36, lvStd = 38, nm = "A Strange Trinket", npc = "Ash Emberhold", npcid = 257591, side = "A", zone = "Riverglades", obj = "For Ash Emberhold of Farholde Keep, take 25 Twilight Amulets from the Twilight Shadowmages and Twilight Neophytes in the Sunlit Woods.", text = "Same batch as \"Shards of Knowledge\": Twilight Shadowmages and Neophytes drop amulets, collect 25; after turning in she gives \"A Small Favor\"." },
    [94886] = { lv = 38, lvStd = 44, nm = "The Western Front", npc = "Commander Brant", npcid = 257558, side = "A", zone = "Riverglades", pre = { 94879 }, obj = "Find Sergeant Riftan near the Twilight's Shroud to the west.", text = "Given by Commander Brant, it sends you west to the Twilight Veil to find Sergeant Riftan; only once you arrive does he give \"No Soldier Left Behind\" and \"Fight Our Way Through\"." },
    [94888] = { lv = 38, lvStd = 44, nm = "Leave No Soldier Behind", npc = "Sergeant Riftan", npcid = 258023, side = "A", zone = "Riverglades", pre = { 94886 }, obj = "Free 5 Farholde Scouts inside the Twilight's Shroud for Sergeant Riftan.", text = "Given by Sergeant Riftan, same batch as \"Fight Our Way Through\"; rescue 5 Farholde Scouts in the Twilight Veil; \"Bring Me Their Heads\" is only given after both are turned in." },
    [94889] = { lv = 38, lvStd = 44, nm = "Cutting a Bloody Path", npc = "Sergeant Riftan", npcid = 258023, side = "A", zone = "Riverglades", pre = { 94886 }, obj = "Defeat 8 Twilight Zealots, 8 Twilight Corruptors and 8 Twilight Champions within the Twilight's Shroud for Sergeant Riftan.", text = "Same batch as \"No Soldier Left Behind\": 8 each of Twilight Zealots, Corruptors and Champions, all in the Twilight's Shroud." },
    [94890] = { lv = 38, lvStd = 46, nm = "Bring Me Their Heads", npc = "Sergeant Riftan", npcid = 258023, side = "A", zone = "Riverglades", pre = { 94888, 94889 }, obj = "Defeat Overlord Kilgar in the Twilight's Shroud and bring his insignia to Sergeant Riftan.", text = "Unlocked only after the first two are turned in; defeat Overlord Kirga in the Twilight Veil and bring the insignia back to Sergeant Riftan; only then can you take \"Twilight Relics\"." },
    [94891] = { lv = 38, lvStd = 46, nm = "News from Farholde", npc = "Sergeant Riftan", npcid = 258023, side = "A", zone = "Riverglades", pre = { 94890 }, obj = "Report to Ash Emberhold at Farholde Keep.", text = "Given by Sergeant Riftan in the Riverglades (30.6,49.0); bring Kilgar's insignia back to Ash Emberhold at Farholde Keep; the Twilight line ends here, and only after this does she give the follow-ups inside the stronghold." },
    [94998] = { lv = 38, lvStd = 42, nm = "Rare Treasures", npc = "Ash Emberhold", npcid = 257591, side = "A", zone = "Riverglades", pre = { 94997 }, obj = "Bring the relic pack to Melanie Sabre.", text = "Follow-up to Twilight Relics: the relic bag looted in the dungeon is purified by Ash Emberhold and then sent to Melanie Sable; this one is not in the dungeon quest list." },
